// REGOLE DI TUTTI I GIOCHI — brevi, a punti, uguali in IT/EN/ES
// Chiave: "categoria|NOME ITALIANO". Valore: {it:[regole, consiglio], en:[…], es:[…], p:"giocatori"}
// Le righe delle regole sono separate da \n e si leggono una sotto l'altra.
// ══════════════════════════════════════════
var REGOLE={
// ───────────── TRA AMICI ─────────────
"amici|È UN 10 MA...":{
 it:["1. L'app mostra una frase: «È un 10, ma…».\n2. Leggetela ad alta voce.\n3. Ognuno dice se ci uscirebbe lo stesso, e perché.\n4. Toccate «Prossima frase» e si continua.","Più il difetto è assurdo, più si ride."],
 en:["1. The app shows a line: \"They're a 10, but…\".\n2. Read it out loud.\n3. Everyone says if they'd still date them, and why.\n4. Tap \"Next phrase\" and keep going.","The weirder the flaw, the bigger the laugh."],
 es:["1. La app muestra una frase: «Es un 10, pero…».\n2. Leedla en voz alta.\n3. Cada uno dice si saldría igual con esa persona, y por qué.\n4. Tocad «Siguiente frase» y seguid.","Cuanto más absurdo el defecto, más risas."]},
"amici|MR. WHITE":{
 it:["1. Passatevi il telefono: ognuno tocca il suo nome e guarda la parola segreta. Uno solo scopre di essere Mr. White e non la vede.\n2. A turno ognuno dice una parola che c'entra con quella segreta.\n3. Poi votate chi è Mr. White.\n4. Se lo scoprite, ha un'ultima occasione: se indovina la parola vince lui, altrimenti vincete voi.","Mr. White: ascolta bene gli altri e bluffa con sicurezza."],
 en:["1. Pass the phone around: everyone taps their name and sees the secret word. One player finds out they're Mr. White and doesn't see it.\n2. Taking turns, everyone says one word linked to the secret one.\n3. Then vote for who Mr. White is.\n4. If you catch them, they get one last chance: guess the word and they win, otherwise you win.","Mr. White: listen carefully and bluff with confidence."],
 es:["1. Pasaos el móvil: cada uno toca su nombre y ve la palabra secreta. Solo uno descubre que es Mr. White y no la ve.\n2. Por turnos, cada uno dice una palabra relacionada con la secreta.\n3. Luego votad quién es Mr. White.\n4. Si lo pilláis, tiene una última oportunidad: si adivina la palabra gana él; si no, ganáis vosotros.","Mr. White: escucha bien a los demás y farolea con seguridad."]},
"amici|PUNTA IL DITO":{
 it:["1. Leggete la frase: «Chi è più probabile che…».\n2. Contate fino a tre e puntate tutti il dito su qualcuno.\n3. Chi ha più dita addosso spiega perché.\n4. Toccate «Prossima frase».","Puntate chi se lo merita, non il più timido."],
 en:["1. Read the line: \"Who's most likely to…\".\n2. Count to three and everyone points at someone.\n3. Whoever gets the most fingers explains why.\n4. Tap \"Next phrase\".","Point at whoever deserves it, not the shyest one."],
 es:["1. Leed la frase: «¿Quién es más probable que…?».\n2. Contad hasta tres y todos señalan a alguien.\n3. Quien reciba más dedos explica por qué.\n4. Tocad «Siguiente frase».","Señalad a quien se lo merece, no al más tímido."]},
"amici|TROVA LA BUGIA":{
 it:["1. A turno, uno dice tre cose su di sé: due vere e una inventata.\n2. Gli altri votano quale è la bugia.\n3. Prende un punto per ogni persona che ha ingannato.\nVince chi alla fine ha più punti.","Una bugia con tanti dettagli sembra sempre vera."],
 en:["1. In turn, one player says three things about themselves: two true, one made up.\n2. The others vote on which one is the lie.\n3. They score a point for each person they fooled.\nMost points at the end wins.","A lie with lots of details always sounds true."],
 es:["1. Por turnos, uno dice tres cosas sobre sí mismo: dos verdaderas y una inventada.\n2. Los demás votan cuál es la mentira.\n3. Gana un punto por cada persona a la que engañó.\nGana quien tenga más puntos al final.","Una mentira con muchos detalles siempre parece verdad."]},
"amici|OPINIONI SCOTTANTI":{
 it:["1. Leggete l'opinione ad alta voce.\n2. Al tre, mano alzata se siete d'accordo, giù se no.\n3. Chi è in minoranza ha 30 secondi per difendersi.\n4. Toccate «Prossima frase».","Le frasi che dividono il tavolo a metà sono le migliori."],
 en:["1. Read the opinion out loud.\n2. On three, hand up if you agree, down if you don't.\n3. The minority gets 30 seconds to defend themselves.\n4. Tap \"Next phrase\".","The best ones split the table in half."],
 es:["1. Leed la opinión en voz alta.\n2. A la de tres, mano arriba si estáis de acuerdo, abajo si no.\n3. Quien quede en minoría tiene 30 segundos para defenderse.\n4. Tocad «Siguiente frase».","Las mejores son las que dividen la mesa por la mitad."]},
"amici|IL SUSSURRO":{
 it:["1. Chi ha il telefono legge la domanda in silenzio e la sussurra al vicino.\n2. Il vicino risponde ad alta voce solo con un nome del tavolo.\n3. Chi è stato nominato può lanciare una moneta: testa, la domanda si legge a tutti; croce, resta segreta.\n4. Passate il telefono e toccate «Prossima frase».","Rispondete senza ridere: il dubbio è il bello del gioco."],
 en:["1. Whoever holds the phone reads the question silently and whispers it to their neighbour.\n2. The neighbour answers out loud with just a name from the table.\n3. The person named can flip a coin: heads, the question is read to everyone; tails, it stays secret.\n4. Pass the phone and tap \"Next phrase\".","Answer with a straight face: the doubt is the fun part."],
 es:["1. Quien tiene el móvil lee la pregunta en silencio y se la susurra al de al lado.\n2. Este responde en voz alta solo con un nombre de la mesa.\n3. La persona nombrada puede lanzar una moneda: cara, la pregunta se lee a todos; cruz, queda en secreto.\n4. Pasad el móvil y tocad «Siguiente frase».","Responded sin reír: la duda es lo divertido."]},
"amici|CHI SONO IO?":{
 it:["1. Uno pensa a un personaggio famoso e lo scrive sul telefono.\n2. Mostra lo schermo a tutti tranne a chi deve indovinare.\n3. Chi indovina fa domande con risposta solo sì o no.\n4. Ha 10 domande per scoprire chi è. Poi si cambia.","Partite da domande larghe: «È una donna?», «È vivo?»."],
 en:["1. One player thinks of a famous person and types it on the phone.\n2. Show the screen to everyone except the guesser.\n3. The guesser asks yes-or-no questions only.\n4. They get 10 questions to find out who it is. Then swap.","Start broad: \"Is it a woman?\", \"Are they alive?\"."],
 es:["1. Uno piensa en un personaje famoso y lo escribe en el móvil.\n2. Enseña la pantalla a todos menos a quien tiene que adivinar.\n3. Quien adivina solo hace preguntas de sí o no.\n4. Tiene 10 preguntas para descubrirlo. Luego se cambia.","Empezad con preguntas amplias: «¿Es mujer?», «¿Está vivo?»."]},
"amici|ALIBI":{
 it:["1. Inventate un crimine buffo (es. «chi ha finito le patatine?»).\n2. Due sospettati si allontanano: hanno 2 minuti per inventare un alibi insieme.\n3. Tornano e vengono interrogati uno alla volta.\n4. Se le loro risposte non coincidono, sono colpevoli!","Gli interroganti vincono con le domande piccole: «di che colore era la tovaglia?»."],
 en:["1. Make up a silly crime (e.g. \"who finished the crisps?\").\n2. Two suspects step away: they get 2 minutes to build an alibi together.\n3. They come back and are questioned one at a time.\n4. If their answers don't match, they're guilty!","Interrogators win with small questions: \"what colour was the tablecloth?\"."],
 es:["1. Inventad un crimen divertido (p. ej. «¿quién se acabó las patatas?»).\n2. Dos sospechosos se apartan: tienen 2 minutos para inventar una coartada juntos.\n3. Vuelven y se les interroga uno a uno.\n4. Si sus respuestas no coinciden, ¡son culpables!","Los interrogadores ganan con preguntas pequeñas: «¿de qué color era el mantel?»."]},
"amici|CONTARE FINO A 21":{
 it:["1. Il gruppo conta da 1 a 21, un numero alla volta.\n2. Nessun ordine fisso: chiunque può dire il numero dopo.\n3. Se due persone parlano insieme, si riparte da 1.\n4. Chi dice 21 inventa una nuova regola (es. «al posto del 7 si batte le mani»).","Guardatevi negli occhi: aiuta più di quanto sembri."],
 en:["1. The group counts from 1 to 21, one number at a time.\n2. No set order: anyone can say the next number.\n3. If two people speak at once, start again from 1.\n4. Whoever says 21 adds a new rule (e.g. \"clap instead of saying 7\").","Look each other in the eye: it helps more than you'd think."],
 es:["1. El grupo cuenta del 1 al 21, un número cada vez.\n2. Sin orden fijo: cualquiera puede decir el siguiente.\n3. Si dos personas hablan a la vez, se vuelve a empezar desde 1.\n4. Quien dice 21 añade una regla nueva (p. ej. «en vez del 7 se da una palmada»).","Miraos a los ojos: ayuda más de lo que parece."]},
"amici|SINCRONIA":{
 it:["1. Due giocatori, al tre, dicono insieme una parola qualsiasi.\n2. Al tre successivo, devono dire una parola che unisce le due appena dette.\n3. Si continua finché dicono la stessa parola nello stesso momento.\n4. Contate quanti tentativi ci sono voluti: meno sono, meglio è.","Non pensate troppo: la prima idea è quasi sempre quella giusta."],
 en:["1. Two players, on three, each say any word at the same time.\n2. On the next three, they must say a word that links the two words just said.\n3. Keep going until they say the same word at the same moment.\n4. Count how many tries it took: fewer is better.","Don't overthink it: the first idea is usually right."],
 es:["1. Dos jugadores, a la de tres, dicen a la vez una palabra cualquiera.\n2. A la siguiente de tres, deben decir una palabra que una las dos anteriores.\n3. Seguid hasta que digan la misma palabra a la vez.\n4. Contad cuántos intentos hicieron falta: cuantos menos, mejor.","No lo penséis mucho: la primera idea suele ser la buena."]},
"amici|SÌ, NO, NON":{
 it:["1. Uno è «sotto torchio» e tocca «Inizia»: parte il tempo.\n2. Gli altri gli fanno domande veloci per fargli dire SÌ, NO o NON.\n3. Lui risponde a tutto senza mai usare quelle parole.\n4. Appena sbaglia, toccate «Ha detto sì/no/non»: l'app segna quanto ha resistito.\nVince chi resiste più a lungo (massimo 3 minuti).","Le domande più semplici sono le più pericolose: «Ti chiami Marco?»."],
 en:["1. One player is in the hot seat and taps \"Start\": the clock runs.\n2. The others fire quick questions to make them say YES, NO or NOT.\n3. They must answer everything without ever using those words.\n4. As soon as they slip, tap \"Said yes/no/not\": the app shows how long they lasted.\nLongest time wins (3 minutes max).","The simplest questions are the deadliest: \"Is your name Mark?\"."],
 es:["1. Uno está «en el banquillo» y toca «Empezar»: corre el tiempo.\n2. Los demás le hacen preguntas rápidas para que diga SÍ, NO o TAMPOCO.\n3. Debe responder a todo sin usar nunca esas palabras.\n4. En cuanto falle, tocad «Ha dicho sí/no/tampoco»: la app muestra cuánto aguantó.\nGana quien aguante más (máximo 3 minutos).","Las preguntas más simples son las más peligrosas: «¿Te llamas Marcos?»."]},
"amici|LA PAROLA GIUSTA":{
 it:["1. Scegliete quante squadre siete e la difficoltà.\n2. Uno della squadra fa indovinare le parole che vede, senza dirle, senza gesti e senza parole della stessa famiglia.\n3. Avete 60 secondi: toccate «Indovinata» per ogni parola presa.\n4. Poi tocca alla squadra dopo.\nQuando smettete, vince la squadra con più parole.","Se la parola è MARE, non si può dire «marino» né «maremoto»."],
 en:["1. Choose how many teams and the difficulty.\n2. One team member gets the others to guess the words on screen, without saying them, without gestures and without words from the same family.\n3. You have 60 seconds: tap \"Correct\" for each word guessed.\n4. Then it's the next team's turn.\nWhen you stop, the team with the most words wins.","If the word is SEA, you can't say \"seaside\" or \"seafood\"."],
 es:["1. Elegid cuántos equipos sois y la dificultad.\n2. Uno del equipo hace adivinar las palabras que ve, sin decirlas, sin gestos y sin palabras de la misma familia.\n3. Tenéis 60 segundos: tocad «Correcta» por cada palabra.\n4. Luego le toca al siguiente equipo.\nCuando paréis, gana el equipo con más palabras.","Si la palabra es MAR, no se puede decir «marino» ni «maremoto»."]},
"amici|NOME E COGNOME":{
 it:["1. Scrivete quanti siete e i vostri nomi.\n2. L'app estrae due lettere: una per il nome, una per il cognome.\n3. Il primo che urla un nome e cognome con quelle iniziali prende il punto (toccate il suo nome).\n4. Se nessuno ci riesce, «Nessuno — nuove lettere».\nVince il primo che arriva a 5 punti.","Vanno bene famosi, amici e anche nomi inventati che suonano veri."],
 en:["1. Enter how many you are and your names.\n2. The app draws two letters: one for the first name, one for the surname.\n3. The first to shout a full name with those initials gets the point (tap their name).\n4. If nobody can, tap \"Nobody — new letters\".\nFirst to 5 points wins.","Famous people, friends, even made-up names that sound real all count."],
 es:["1. Poned cuántos sois y vuestros nombres.\n2. La app saca dos letras: una para el nombre y otra para el apellido.\n3. El primero que grite un nombre y apellido con esas iniciales gana el punto (tocad su nombre).\n4. Si nadie lo consigue, «Nadie — nuevas letras».\nGana el primero que llegue a 5 puntos.","Valen famosos, amigos e incluso nombres inventados que suenen reales."]},
"amici|QUINDICI":{
 it:["1. Scrivete quanti siete e i vostri nomi.\n2. Al tuo turno tocca il dado.\n3. Scegli: aggiungi il numero ai tuoi punti, oppure toglilo a un avversario.\n4. Se superi 15 torni a 0.\nVince chi arriva esattamente a 15.","Quando qualcuno è vicino a 15, fatelo scendere!"],
 en:["1. Enter how many you are and your names.\n2. On your turn, tap the die.\n3. Choose: add the number to your score, or take it away from an opponent.\n4. Go over 15 and you drop back to 0.\nFirst to land exactly on 15 wins.","When someone gets close to 15, knock them down!"],
 es:["1. Poned cuántos sois y vuestros nombres.\n2. En tu turno toca el dado.\n3. Elige: sumas el número a tus puntos o se lo restas a un rival.\n4. Si pasas de 15 vuelves a 0.\nGana quien llegue exactamente a 15.","¡Cuando alguien esté cerca de 15, hacedlo bajar!"]},
"amici|INDOVINA IL CODICE":{
 it:["1. Scrivete i nomi. Ognuno, di nascosto, sceglie un codice segreto di 4 cifre.\n2. Al tuo turno scegli di chi indovinare il codice e scrivi 4 cifre.\n3. Verde = cifra giusta al posto giusto. Giallo = cifra giusta al posto sbagliato.\nVince chi indovina per primo un codice intero.\nDa soli: l'app sceglie un codice e tu lo scopri con meno tentativi possibile.","Guardate anche i tentativi degli altri: sono indizi per tutti."],
 en:["1. Enter the names. Each player secretly picks a 4-digit code.\n2. On your turn, choose whose code to crack and type 4 digits.\n3. Green = right digit, right place. Yellow = right digit, wrong place.\nFirst to crack a whole code wins.\nAlone: the app picks a code and you crack it in as few tries as possible.","Watch the others' tries too: they're clues for everyone."],
 es:["1. Poned los nombres. Cada uno, a escondidas, elige un código secreto de 4 cifras.\n2. En tu turno elige de quién adivinar el código y escribe 4 cifras.\n3. Verde = cifra correcta en su sitio. Amarillo = cifra correcta en otro sitio.\nGana quien adivine primero un código entero.\nSolo: la app elige un código y tú lo descubres en los menos intentos posibles.","Mirad también los intentos de los demás: son pistas para todos."]},
"amici|L'OCCHIO DEI COLORI":{
 p:"1-20",
 it:["1. Scegliete quanti siete e il livello.\n2. A turno, sullo stesso telefono, ognuno mette in ordine di sfumatura le stesse 4 file di colori.\n3. Le strisce col puntino restano ferme: sposta le altre trascinandole o toccandole.\nVince il più preciso. Se c'è parità, chi è pari rifà una prova più difficile.","Chi aspetta il turno non guarda: i colori sono uguali per tutti."],
 en:["1. Choose how many you are and the level.\n2. Taking turns on the same phone, everyone sorts the same 4 rows of colours by shade.\n3. Stripes with a dot stay put: move the others by dragging or tapping.\nMost precise wins. If there's a tie, the tied players redo a harder round.","Whoever's waiting doesn't look: the colours are the same for everyone."],
 es:["1. Elegid cuántos sois y el nivel.\n2. Por turnos, en el mismo móvil, cada uno ordena por tono las mismas 4 filas de colores.\n3. Las franjas con punto no se mueven: mueve las demás arrastrando o tocando.\nGana el más preciso. Si hay empate, los empatados repiten una prueba más difícil.","Quien espera su turno no mira: los colores son iguales para todos."]},
"amici|CHE LINGUA È?":{
 p:"1-10",
 it:["1. Scegliete quanti siete e il livello.\n2. L'app mostra una frase in un'altra lingua.\n3. A turno, ognuno sceglie la lingua giusta tra 4, senza farsi vedere.\n4. Poi si scopre la soluzione, con il paese e il significato.\n10 frasi: un punto per ogni risposta giusta. Se c'è parità, altre 3 frasi finché uno vince.","Guardate le lettere strane e gli accenti: ogni lingua ha i suoi."],
 en:["1. Choose how many you are and the level.\n2. The app shows a sentence in another language.\n3. Taking turns, everyone picks the right language out of 4, without showing the others.\n4. Then the answer appears, with the country and the meaning.\n10 sentences: one point per right answer. If there's a tie, 3 more sentences until someone wins.","Look at the odd letters and accents: every language has its own."],
 es:["1. Elegid cuántos sois y el nivel.\n2. La app muestra una frase en otro idioma.\n3. Por turnos, cada uno elige el idioma correcto entre 4, sin que los demás lo vean.\n4. Luego sale la solución, con el país y el significado.\n10 frases: un punto por acierto. Si hay empate, 3 frases más hasta que gane uno.","Fijaos en las letras raras y los acentos: cada idioma tiene los suyos."]},
// ───────────── LA COPPIA ─────────────
"coppia|36 DOMANDE":{
 it:["1. Leggete una domanda alla volta, ad alta voce.\n2. Rispondete tutti e due, a turno.\n3. Ci sono 3 round, dal più leggero al più profondo.\nNon c'è fretta: ascoltatevi davvero.\nFonte: A. Aron, E. Melinat, E. N. Aron, R. D. Vallone, R. J. Bator, «The Experimental Generation of Interpersonal Closeness: A Procedure and Some Preliminary Findings», Personality and Social Psychology Bulletin, 23(4), 363–377, 1997 (traduzione italiana di Filòs).","La pausa dopo ogni risposta fa parte del gioco."],
 en:["1. Read one question at a time, out loud.\n2. You both answer, taking turns.\n3. There are 3 rounds, from lightest to deepest.\nNo rush: really listen to each other.\nSource: A. Aron, E. Melinat, E. N. Aron, R. D. Vallone, R. J. Bator, \"The Experimental Generation of Interpersonal Closeness: A Procedure and Some Preliminary Findings\", Personality and Social Psychology Bulletin, 23(4), 363–377, 1997.","The pause after each answer is part of the game."],
 es:["1. Leed una pregunta cada vez, en voz alta.\n2. Respondéis los dos, por turnos.\n3. Hay 3 rondas, de la más ligera a la más profunda.\nSin prisa: escuchaos de verdad.\nFuente: A. Aron, E. Melinat, E. N. Aron, R. D. Vallone, R. J. Bator, «The Experimental Generation of Interpersonal Closeness: A Procedure and Some Preliminary Findings», Personality and Social Psychology Bulletin, 23(4), 363–377, 1997 (traducción española de Filòs).","La pausa después de cada respuesta es parte del juego."]},
"coppia|È UN 10 MA... (COPPIA)":{
 it:["1. A turno, descrivi l'altro con «Sei un 10, ma…» e aggiungi un piccolo difetto affettuoso.\n2. L'altro risponde: «Lo accetti così?».\n3. Poi tocca a lui.","Più il «ma» è tenero e preciso, più vale."],
 en:["1. Taking turns, describe the other with \"You're a 10, but…\" and add a small, loving flaw.\n2. The other replies: \"Do you take me like this?\".\n3. Then it's their turn.","The sweeter and more specific the \"but\", the better."],
 es:["1. Por turnos, describe al otro con «Eres un 10, pero…» y añade un pequeño defecto cariñoso.\n2. El otro responde: «¿Me aceptas así?».\n3. Luego le toca a él.","Cuanto más tierno y concreto el «pero», mejor."]},
"coppia|CHI È PIÙ PROBABILE? (COPPIA)":{
 it:["1. Leggete la frase: «Chi di noi è più probabile che…».\n2. Al tre, puntate tutti e due il dito: su di voi o sull'altro.\n3. Se non siete d'accordo, spiegatevi!\n4. Toccate «Prossima frase».","Più siete sinceri, più vi divertite."],
 en:["1. Read the line: \"Which of us is more likely to…\".\n2. On three, you both point: at yourself or at the other.\n3. If you disagree, explain yourselves!\n4. Tap \"Next phrase\".","The more honest you are, the more fun it gets."],
 es:["1. Leed la frase: «¿Quién de nosotros es más probable que…?».\n2. A la de tres, señaláis los dos: a vosotros mismos o al otro.\n3. Si no coincidís, ¡explicaos!\n4. Tocad «Siguiente frase».","Cuanto más sinceros, más divertido."]},
"coppia|VERO O FALSO?":{
 it:["1. Uno racconta tre cose su di sé: due vere e una inventata.\n2. L'altro indovina qual è la bugia.\n3. Poi si scambiano.","I ricordi d'infanzia sono i più sorprendenti."],
 en:["1. One tells three things about themselves: two true, one made up.\n2. The other guesses which is the lie.\n3. Then swap.","Childhood memories are the most surprising."],
 es:["1. Uno cuenta tres cosas sobre sí mismo: dos verdaderas y una inventada.\n2. El otro adivina cuál es la mentira.\n3. Luego cambiáis.","Los recuerdos de la infancia son los más sorprendentes."]},
"coppia|SE FOSSI...":{
 it:["1. Uno pensa a una persona, un oggetto o un posto, senza dirlo.\n2. L'altro chiede: «Se fosse un piatto, cosa sarebbe?», «Se fosse un colore?»…\n3. Quando pensa di aver capito, prova a indovinare.\n4. Poi si scambiano.","Le risposte dicono molto anche su chi risponde."],
 en:["1. One thinks of a person, an object or a place, without saying it.\n2. The other asks: \"If it were a dish, what would it be?\", \"If it were a colour?\"…\n3. When they think they've got it, they guess.\n4. Then swap.","The answers say a lot about who's answering, too."],
 es:["1. Uno piensa en una persona, un objeto o un lugar, sin decirlo.\n2. El otro pregunta: «Si fuera un plato, ¿cuál sería?», «¿Y si fuera un color?»…\n3. Cuando crea que lo tiene, intenta adivinarlo.\n4. Luego cambiáis.","Las respuestas también dicen mucho de quien responde."]},
"coppia|MAPPA DEI SOGNI":{
 it:["1. Uno racconta 5 desideri per il futuro, dal più semplice al più grande.\n2. L'altro ascolta senza interrompere.\n3. Poi si scambiano.","Ascoltate davvero, senza pensare già alla risposta."],
 en:["1. One shares 5 wishes for the future, from the simplest to the biggest.\n2. The other listens without interrupting.\n3. Then swap.","Really listen, without planning your reply."],
 es:["1. Uno cuenta 5 deseos para el futuro, del más sencillo al más grande.\n2. El otro escucha sin interrumpir.\n3. Luego cambiáis.","Escuchad de verdad, sin pensar ya en la respuesta."]},
"coppia|IL GIOCO DEL QUANDO":{
 it:["1. A turno fate all'altro una domanda che inizia con «Quando…» (es. «Quando hai capito che ti piacevo?»).\n2. L'altro risponde con sincerità.\n3. Poi tocca a lui fare la domanda.","Le risposte piccole e precise sono le più belle."],
 en:["1. Taking turns, ask the other a question starting with \"When…\" (e.g. \"When did you know you liked me?\").\n2. The other answers honestly.\n3. Then it's their turn to ask.","Small, specific answers are the best ones."],
 es:["1. Por turnos, hacedle al otro una pregunta que empiece por «¿Cuándo…?» (p. ej. «¿Cuándo supiste que te gustaba?»).\n2. El otro responde con sinceridad.\n3. Luego le toca preguntar a él.","Las respuestas pequeñas y concretas son las más bonitas."]},
"coppia|COSA NON SAI DI ME":{
 it:["1. A turno, di nascosto, ognuno scrive 5 cose su di sé: vere o inventate.\n2. Poi uno legge una sua frase ad alta voce.\n3. L'altro dice se è vera o falsa, e si scopre la risposta.\n4. Si continua alternandosi.","Mescolate cose vere incredibili e bugie normalissime."],
 en:["1. Taking turns, secretly, each of you writes 5 things about yourself: true or made up.\n2. Then one reads one of theirs out loud.\n3. The other says if it's true or false, and the answer is revealed.\n4. Keep going, taking turns.","Mix unbelievable truths with very normal lies."],
 es:["1. Por turnos, a escondidas, cada uno escribe 5 cosas sobre sí mismo: verdaderas o inventadas.\n2. Luego uno lee una de las suyas en voz alta.\n3. El otro dice si es verdad o mentira, y se descubre la respuesta.\n4. Seguid alternándoos.","Mezclad verdades increíbles con mentiras normalísimas."]},
"coppia|IL VIAGGIO DEI SOGNI":{
 it:["1. Rispondete insieme alle domande: dove, quando, quanto, cosa fate…\n2. Ogni scelta va decisa in due.\n3. Alla fine toccate «Vedi il vostro viaggio»: l'app vi mostra la scheda del vostro viaggio.","Non ci sono limiti di soldi: sognate in grande."],
 en:["1. Answer the questions together: where, when, how long, what you do…\n2. Every choice must be agreed by both.\n3. At the end tap \"See your trip\": the app shows your trip card.","There's no budget limit: dream big."],
 es:["1. Responded juntos a las preguntas: dónde, cuándo, cuánto tiempo, qué hacéis…\n2. Cada decisión se toma entre los dos.\n3. Al final tocad «Ver vuestro viaje»: la app os muestra la ficha del viaje.","No hay límite de dinero: soñad a lo grande."]},
"coppia|IL COMPLIMENTO SPECIFICO":{
 it:["1. Uno fa all'altro 5 complimenti, ma molto precisi.\n2. Non «sei bello», ma «mi piace come sorridi quando ridi tanto».\n3. L'altro ascolta senza rispondere. Poi si scambiano.","Un complimento preciso vale dieci complimenti generici."],
 en:["1. One gives the other 5 compliments, but very specific ones.\n2. Not \"you're handsome\", but \"I love how you smile after laughing hard\".\n3. The other listens without replying. Then swap.","One specific compliment is worth ten generic ones."],
 es:["1. Uno le hace al otro 5 cumplidos, pero muy concretos.\n2. No «eres guapo», sino «me encanta cómo sonríes después de reírte mucho».\n3. El otro escucha sin responder. Luego cambiáis.","Un cumplido concreto vale por diez genéricos."]},
"coppia|LA LINEA DEL TEMPO":{
 it:["1. Uno racconta i 5 momenti più importanti della sua vita, in ordine.\n2. L'altro ascolta in silenzio.\n3. Alla fine fa una sola domanda, su ciò che l'ha colpito di più.\n4. Poi si scambiano.","Quello che uno sceglie di raccontare dice chi è."],
 en:["1. One tells the 5 most important moments of their life, in order.\n2. The other listens in silence.\n3. At the end they ask just one question, about what struck them most.\n4. Then swap.","What someone chooses to tell shows who they are."],
 es:["1. Uno cuenta los 5 momentos más importantes de su vida, en orden.\n2. El otro escucha en silencio.\n3. Al final hace una sola pregunta, sobre lo que más le ha llamado la atención.\n4. Luego cambiáis.","Lo que uno elige contar dice quién es."]},
"coppia|PAURE E CORAGGIO":{
 it:["1. Uno risponde a due domande: «Qual è la tua paura più grande?» e «Qual è la cosa più coraggiosa che hai fatto?».\n2. L'altro ascolta senza commentare, poi fa una sola domanda.\n3. Poi si scambiano.","Condividere una paura avvicina più di tutto."],
 en:["1. One answers two questions: \"What's your biggest fear?\" and \"What's the bravest thing you've done?\".\n2. The other listens without commenting, then asks just one question.\n3. Then swap.","Sharing a fear brings you closer than anything."],
 es:["1. Uno responde a dos preguntas: «¿Cuál es tu mayor miedo?» y «¿Qué es lo más valiente que has hecho?».\n2. El otro escucha sin comentar y luego hace una sola pregunta.\n3. Luego cambiáis.","Compartir un miedo une más que nada."]},
"coppia|LA VERSIONE DI TE":{
 it:["1. Uno risponde: «Come saresti se non avessi mai avuto paura?» e «Come vorresti essere tra 10 anni?».\n2. L'altro ascolta, poi dice cosa vede già di quella persona in lui.\n3. Poi si scambiano.","Spesso l'altro vede in noi cose che noi non vediamo."],
 en:["1. One answers: \"Who would you be if you'd never been afraid?\" and \"Who do you want to be in 10 years?\".\n2. The other listens, then says what they already see of that person in them.\n3. Then swap.","Others often see things in us that we don't."],
 es:["1. Uno responde: «¿Cómo serías si nunca hubieras tenido miedo?» y «¿Cómo te gustaría ser dentro de 10 años?».\n2. El otro escucha y luego dice qué ve ya de esa persona en él.\n3. Luego cambiáis.","A menudo el otro ve en nosotros cosas que nosotros no vemos."]},
"coppia|LA MAPPA DELL'ALTRO":{
 it:["1. Leggete una domanda alla volta.\n2. Rispondete tutti e due, a turno.\n3. Nessuno giudica le risposte dell'altro.\nIspirato agli studi di John Gottman sulle coppie.","Le coppie che si conoscono a fondo superano meglio i momenti difficili."],
 en:["1. Read one question at a time.\n2. You both answer, taking turns.\n3. Nobody judges the other's answers.\nInspired by John Gottman's research on couples.","Couples who know each other deeply get through hard times better."],
 es:["1. Leed una pregunta cada vez.\n2. Respondéis los dos, por turnos.\n3. Nadie juzga las respuestas del otro.\nInspirado en los estudios de John Gottman sobre parejas.","Las parejas que se conocen a fondo superan mejor los momentos difíciles."]},
"coppia|IL GIOCO DELLA VULNERABILITÀ":{
 it:["1. Leggete una domanda alla volta: ci sono 3 livelli.\n2. Rispondete a turno, con sincerità.\n3. Mai sminuire la risposta dell'altro.\nIspirato al lavoro di Brené Brown sul coraggio e la vulnerabilità.","Non servono risposte grandi: servono risposte vere."],
 en:["1. Read one question at a time: there are 3 levels.\n2. Answer in turn, honestly.\n3. Never play down the other's answer.\nInspired by Brené Brown's work on courage and vulnerability.","Answers don't need to be big: they need to be true."],
 es:["1. Leed una pregunta cada vez: hay 3 niveles.\n2. Responded por turnos, con sinceridad.\n3. Nunca le quitéis importancia a la respuesta del otro.\nInspirado en el trabajo de Brené Brown sobre el valor y la vulnerabilidad.","No hacen falta respuestas grandes: hacen falta respuestas sinceras."]},
"coppia|LE DOMANDE DEI 3 LIVELLI":{
 it:["1. Leggete una domanda alla volta: 3 round, sempre più profondi.\n2. Uno risponde, l'altro ascolta senza interrompere.\n3. Poi si scambiano.\nIspirato alla terapia ACT di Steven Hayes, che lavora sui valori.","Non chiedono cosa hai fatto, ma cosa conta per te."],
 en:["1. Read one question at a time: 3 rounds, each deeper.\n2. One answers, the other listens without interrupting.\n3. Then swap.\nInspired by Steven Hayes's ACT therapy, which works on values.","They don't ask what you did, but what matters to you."],
 es:["1. Leed una pregunta cada vez: 3 rondas, cada vez más profundas.\n2. Uno responde y el otro escucha sin interrumpir.\n3. Luego cambiáis.\nInspirado en la terapia ACT de Steven Hayes, que trabaja sobre los valores.","No preguntan qué hiciste, sino qué te importa."]},
"coppia|IL METODO DELL'APPREZZAMENTO":{
 it:["1. Leggete una domanda alla volta.\n2. Rispondete a turno.\n3. Unica regola: ogni risposta deve dire qualcosa di bello sull'altro, che hai notato davvero.\nIspirato agli studi di John Gottman su stima e affetto.","Le frasi più forti sono quelle che l'altro non sa che hai notato."],
 en:["1. Read one question at a time.\n2. Answer in turn.\n3. Only rule: every answer must say something nice about the other, something you really noticed.\nInspired by John Gottman's research on fondness and admiration.","The strongest ones are things they didn't know you'd noticed."],
 es:["1. Leed una pregunta cada vez.\n2. Responded por turnos.\n3. Única regla: cada respuesta debe decir algo bonito del otro, algo que hayas notado de verdad.\nInspirado en los estudios de John Gottman sobre aprecio y cariño.","Lo más fuerte es lo que el otro no sabe que has notado."]},
// ───────────── ROMPIGHIACCIO ─────────────
"bambini|APPELLO":{
 it:["1. Toccate «Inizia memorizzazione»: avete 60 secondi per imparare i nomi di tutti al tavolo.\n2. Poi uno indica una persona a caso.\n3. Un altro ha 3 secondi per dire il suo nome.\n4. Chi sbaglia è fuori.\nVince l'ultimo rimasto.","Perfetto appena ci si siede tra sconosciuti."],
 en:["1. Tap \"Start memorising\": you have 60 seconds to learn everyone's name at the table.\n2. Then someone points at a random person.\n3. Another player has 3 seconds to say their name.\n4. Get it wrong and you're out.\nLast one standing wins.","Perfect right after sitting down with strangers."],
 es:["1. Tocad «Empezar a memorizar»: tenéis 60 segundos para aprender el nombre de todos en la mesa.\n2. Luego uno señala a alguien al azar.\n3. Otro tiene 3 segundos para decir su nombre.\n4. Quien falla queda fuera.\nGana el último que quede.","Perfecto nada más sentarse entre desconocidos."]},
"bambini|MI CHIAMO E MI PIACE...":{
 it:["1. Il primo dice il suo nome e una cosa che gli piace con la stessa iniziale («Sono Marco e mi piace la montagna»).\n2. Il secondo ripete il primo e poi aggiunge il suo.\n3. Ognuno ripete tutti quelli prima e aggiunge il suo.\n4. Chi sbaglia fa ripartire il giro da capo.","Più si va avanti, più si ride."],
 en:["1. The first says their name and something they like with the same initial (\"I'm Mark and I like mountains\").\n2. The second repeats the first, then adds theirs.\n3. Everyone repeats all the ones before and adds their own.\n4. Whoever slips starts the round again from scratch.","The further you go, the funnier it gets."],
 es:["1. El primero dice su nombre y algo que le gusta con la misma inicial («Soy Marta y me gusta la montaña»).\n2. El segundo repite al primero y añade el suyo.\n3. Cada uno repite todos los anteriores y añade el suyo.\n4. Quien falla hace empezar la ronda desde el principio.","Cuanto más avanzáis, más risas."]},
"bambini|IL SUPERPOTERE":{
 it:["1. A turno, scegli un superpotere e tocca «Inizia il turno».\n2. Hai 30 secondi per raccontare cosa ci faresti oggi.\n3. Gli altri ascoltano in silenzio.\nAlla fine votate il superpotere più originale.","I poteri più semplici, usati con fantasia, sono i più divertenti."],
 en:["1. In turn, pick a superpower and tap \"Start the turn\".\n2. You have 30 seconds to say what you'd do with it today.\n3. The others listen in silence.\nAt the end, vote for the most original superpower.","The simplest powers, used creatively, are the funniest."],
 es:["1. Por turnos, elige un superpoder y toca «Empezar el turno».\n2. Tienes 30 segundos para contar qué harías con él hoy.\n3. Los demás escuchan en silencio.\nAl final votad el superpoder más original.","Los poderes más simples, usados con imaginación, son los más divertidos."]},
"bambini|SCALA DA 1 A 10":{
 it:["1. Leggete la domanda: l'app spiega cosa vuol dire 1 e cosa vuol dire 10.\n2. Al tre, tutti mostrano con le dita il proprio voto da 1 a 10.\n3. Chi ha dato il voto più alto e più basso spiega perché.\n4. Toccate «Prossima frase».","Nessuno giudica: si ride e ci si conosce."],
 en:["1. Read the question: the app explains what 1 and 10 mean.\n2. On three, everyone shows their score from 1 to 10 with their fingers.\n3. Whoever gave the highest and the lowest explains why.\n4. Tap \"Next phrase\".","No judging: just laugh and get to know each other."],
 es:["1. Leed la pregunta: la app explica qué significa 1 y qué significa 10.\n2. A la de tres, todos enseñan con los dedos su nota del 1 al 10.\n3. Quien dio la nota más alta y la más baja explica por qué.\n4. Tocad «Siguiente frase».","Nadie juzga: se ríe y os conocéis."]},
"bambini|DUE VERITÀ E UNA BUGIA":{
 it:["1. A turno, uno dice tre cose su di sé: due vere e una inventata.\n2. Gli altri votano quale è la bugia.\n3. Prende un punto per ogni persona che ha ingannato.\nVince chi alla fine ha più punti.","Le verità più strane sembrano sempre bugie."],
 en:["1. In turn, one player says three things about themselves: two true, one made up.\n2. The others vote on which one is the lie.\n3. They score a point for each person they fooled.\nMost points at the end wins.","The weirdest truths always sound like lies."],
 es:["1. Por turnos, uno dice tres cosas sobre sí mismo: dos verdaderas y una inventada.\n2. Los demás votan cuál es la mentira.\n3. Gana un punto por cada persona a la que engañó.\nGana quien tenga más puntos al final.","Las verdades más raras siempre parecen mentira."]},
"bambini|CHI SEI DAVVERO?":{
 it:["1. Uno fa una domanda a tutti (es. «Se fossi un animale, quale saresti?»).\n2. Toccate «Inizia il round»: avete 20 secondi per rispondere.\n3. Tutti rispondono di getto e spiegano in breve.\nNon ci sono risposte sbagliate.","La prima risposta che vi viene è quella più vera."],
 en:["1. One player asks everyone a question (e.g. \"If you were an animal, which one?\").\n2. Tap \"Start the round\": you have 20 seconds to answer.\n3. Everyone answers on instinct and briefly explains.\nThere are no wrong answers.","Your first answer is the most honest one."],
 es:["1. Uno hace una pregunta a todos (p. ej. «Si fueras un animal, ¿cuál serías?»).\n2. Tocad «Empezar la ronda»: tenéis 20 segundos para responder.\n3. Todos responden sin pensar y lo explican en breve.\nNo hay respuestas incorrectas.","La primera respuesta que os sale es la más sincera."]},
"bambini|COSA HAI IN COMUNE?":{
 it:["1. Formate delle coppie a caso.\n2. Toccate «Inizia»: ogni coppia ha 4 minuti.\n3. Trovate almeno 3 cose inaspettate che avete in comune.\n4. Poi ogni coppia le racconta al tavolo.\nVince la coppia con le somiglianze più strane.","«Ci piace la pizza» non vale: cercate le cose sorprendenti."],
 en:["1. Form random pairs.\n2. Tap \"Start\": each pair gets 4 minutes.\n3. Find at least 3 unexpected things you have in common.\n4. Then each pair tells the table.\nThe pair with the strangest similarities wins.","\"We both like pizza\" doesn't count: look for surprising stuff."],
 es:["1. Formad parejas al azar.\n2. Tocad «Empezar»: cada pareja tiene 4 minutos.\n3. Encontrad al menos 3 cosas inesperadas en común.\n4. Luego cada pareja las cuenta a la mesa.\nGana la pareja con las coincidencias más raras.","«Nos gusta la pizza» no vale: buscad cosas sorprendentes."]},
"bambini|IL MAGO":{
 it:["1. Uno fa il Mago e si allontana.\n2. Gli altri scelgono in segreto una persona del tavolo.\n3. Il Mago torna e chiede: «Se fosse un colore? Un film? Un piatto?».\n4. Rispondete pensando a quella persona: il Mago deve indovinare chi è.","Le risposte dicono qualcosa anche di chi le dà."],
 en:["1. One player is the Wizard and steps away.\n2. The others secretly pick someone at the table.\n3. The Wizard comes back and asks: \"If they were a colour? A film? A dish?\".\n4. Answer thinking of that person: the Wizard must guess who it is.","The answers say something about whoever gives them too."],
 es:["1. Uno hace de Mago y se aparta.\n2. Los demás eligen en secreto a una persona de la mesa.\n3. El Mago vuelve y pregunta: «¿Si fuera un color? ¿Una película? ¿Un plato?».\n4. Responded pensando en esa persona: el Mago tiene que adivinar quién es.","Las respuestas también dicen algo de quien las da."]},
"bambini|IL SOPRANNOME":{
 it:["1. Toccate «Inizia la conversazione»: chiacchierate liberamente per 5 minuti.\n2. Allo scadere, ognuno pensa a un soprannome simpatico per chi ha alla sua destra.\n3. Al tre, li dite tutti insieme.","Simpatici, mai offensivi: è una festa, non una critica."],
 en:["1. Tap \"Start talking\": talk freely for 5 minutes.\n2. When time's up, everyone thinks of a friendly nickname for the person on their right.\n3. On three, say them all together.","Friendly, never mean: it's a celebration, not a roast."],
 es:["1. Tocad «Empezar la conversación»: charlad libremente 5 minutos.\n2. Al terminar, cada uno piensa un apodo simpático para quien tiene a su derecha.\n3. A la de tres, los decís todos a la vez.","Simpáticos, nunca ofensivos: es una fiesta, no una crítica."]},
"bambini|IL VIAGGIO DEI SOGNI":{
 it:["1. Uno racconta il viaggio che farebbe se partisse domani, senza limiti di soldi: dove, con chi, per quanto.\n2. L'altro fa 3 domande e propone una modifica.\n3. Trovate insieme un viaggio che piace a tutti e due.","Come uno viaggia dice molto di come vive."],
 en:["1. One describes the trip they'd take if they left tomorrow, with no budget limit: where, with whom, for how long.\n2. The other asks 3 questions and suggests a change.\n3. Together, find a trip you'd both love.","How someone travels says a lot about how they live."],
 es:["1. Uno cuenta el viaje que haría si saliera mañana, sin límite de dinero: dónde, con quién, cuánto tiempo.\n2. El otro hace 3 preguntas y propone un cambio.\n3. Encontrad juntos un viaje que os guste a los dos.","Cómo viaja alguien dice mucho de cómo vive."]},
"bambini|LA PRIMA VOLTA CHE...":{
 it:["1. A turno raccontate una vostra «prima volta»: la prima canzone amata, il primo viaggio, il primo lavoro…\n2. L'altro ascolta e fa una sola domanda per saperne di più.\n3. Poi si scambiano.","I primi ricordi dicono molto di chi siamo oggi."],
 en:["1. Taking turns, tell one of your \"firsts\": first song you loved, first trip, first job…\n2. The other listens and asks just one question to know more.\n3. Then swap.","First memories say a lot about who we are today."],
 es:["1. Por turnos, contad una «primera vez»: la primera canción que te encantó, el primer viaje, el primer trabajo…\n2. El otro escucha y hace una sola pregunta para saber más.\n3. Luego cambiáis.","Los primeros recuerdos dicen mucho de quiénes somos hoy."]},
"bambini|SE FOSSI...":{
 it:["1. Uno pensa a un oggetto, un animale, un posto o un personaggio famoso, senza dirlo.\n2. L'altro chiede: «Se fosse un piatto, cosa sarebbe?», «Se fosse una città?»…\n3. Quando pensa di aver capito, prova a indovinare.\n4. Poi si scambiano.","Le risposte dicono molto anche su chi risponde."],
 en:["1. One thinks of an object, an animal, a place or a famous person, without saying it.\n2. The other asks: \"If it were a dish, what would it be?\", \"If it were a city?\"…\n3. When they think they've got it, they guess.\n4. Then swap.","The answers say a lot about who's answering, too."],
 es:["1. Uno piensa en un objeto, un animal, un lugar o un famoso, sin decirlo.\n2. El otro pregunta: «Si fuera un plato, ¿cuál sería?», «¿Y si fuera una ciudad?»…\n3. Cuando crea que lo tiene, intenta adivinarlo.\n4. Luego cambiáis.","Las respuestas también dicen mucho de quien responde."]},
"bambini|IL GIOCO DELLE DOMANDE":{
 it:["1. Ognuno scrive su 3 foglietti 3 domande curiose per l'altro.\n2. Mescolate i foglietti e pescatene uno alla volta.\n3. Si risponde sinceramente, ma si può anche passare.","Sono le domande che non avreste il coraggio di fare: ora potete."],
 en:["1. Each of you writes 3 curious questions for the other on 3 slips of paper.\n2. Mix them up and draw one at a time.\n3. Answer honestly, but you can also pass.","They're the questions you'd never dare ask: now you can."],
 es:["1. Cada uno escribe en 3 papelitos 3 preguntas curiosas para el otro.\n2. Mezcladlos y sacad uno cada vez.\n3. Se responde con sinceridad, pero también se puede pasar.","Son las preguntas que nunca os atreveríais a hacer: ahora podéis."]},
"bambini|L'ANNO PERFETTO":{
 it:["1. Uno racconta il suo anno perfetto: dove vivrebbe, che lavoro farebbe, con chi starebbe.\n2. L'altro ascolta senza interrompere, poi fa 3 domande.\n3. Poi si scambiano.","I sogni per il futuro dicono molto del presente."],
 en:["1. One describes their perfect year: where they'd live, what they'd do for work, who they'd be with.\n2. The other listens without interrupting, then asks 3 questions.\n3. Then swap.","Dreams for the future say a lot about the present."],
 es:["1. Uno cuenta su año perfecto: dónde viviría, en qué trabajaría, con quién estaría.\n2. El otro escucha sin interrumpir y luego hace 3 preguntas.\n3. Luego cambiáis.","Los sueños de futuro dicen mucho del presente."]},
"bambini|CONFESSIONI LEGGERE":{
 it:["1. A turno, confessate una piccola stranezza un po' imbarazzante (es. «Controllo il meteo ogni mattina anche se non esco»).\n2. L'altro risponde con una sua: «Capito… e io confesso che…».\n3. Niente segreti pesanti: restate sul leggero.","Le piccole manie avvicinano più dei grandi segreti."],
 en:["1. Taking turns, confess a small, slightly embarrassing quirk (e.g. \"I check the weather every morning even when I'm not going out\").\n2. The other answers with one of theirs: \"Got it… and I confess that…\".\n3. No heavy secrets: keep it light.","Little quirks bring people closer than big secrets."],
 es:["1. Por turnos, confesad una pequeña manía un poco vergonzosa (p. ej. «Miro el tiempo cada mañana aunque no vaya a salir»).\n2. El otro responde con una suya: «Vale… y yo confieso que…».\n3. Nada de secretos pesados: en plan ligero.","Las pequeñas manías unen más que los grandes secretos."]},
"bambini|IL FILM DELLA TUA VITA":{
 it:["1. Uno immagina che la sua vita sia un film: che genere è? Chi fa la sua parte? Qual è la scena più bella?\n2. L'altro fa tutte le domande che vuole.\n3. Poi si scambiano.","Il genere che scegli racconta come vivi."],
 en:["1. One imagines their life is a film: what genre? Who plays them? What's the best scene?\n2. The other asks anything they like.\n3. Then swap.","The genre you choose shows how you live."],
 es:["1. Uno imagina que su vida es una película: ¿de qué género? ¿Quién le interpreta? ¿Cuál es la mejor escena?\n2. El otro pregunta lo que quiera.\n3. Luego cambiáis.","El género que eliges cuenta cómo vives."]},
"bambini|LISTE VELOCI":{
 it:["1. Uno propone una categoria (es. «3 canzoni che ti descrivono»).\n2. Ognuno ha 30 secondi per dire più cose possibili.\n3. Poi confrontate le liste e cambiate categoria.","Rispondete veloci: le risposte di getto sono le più sincere."],
 en:["1. One suggests a category (e.g. \"3 songs that describe you\").\n2. Everyone gets 30 seconds to name as many things as possible.\n3. Then compare lists and switch category.","Answer fast: instant answers are the most honest."],
 es:["1. Uno propone una categoría (p. ej. «3 canciones que te describen»).\n2. Cada uno tiene 30 segundos para decir todo lo que pueda.\n3. Luego comparad las listas y cambiad de categoría.","Responded rápido: las respuestas instantáneas son las más sinceras."]},
"bambini|IL MUSEO DELLA TUA VITA":{
 it:["1. Uno sceglie 5 oggetti che metterebbe nel museo della sua vita: non preziosi, ma importanti per lui.\n2. Racconta in breve la storia di ognuno.\n3. L'altro sceglie l'oggetto di cui vuole sapere di più.\n4. Poi si scambiano.","Gli oggetti raccontano una persona meglio di qualsiasi presentazione."],
 en:["1. One picks 5 objects for the museum of their life: not valuable, but meaningful to them.\n2. They briefly tell the story of each.\n3. The other picks the object they want to hear more about.\n4. Then swap.","Objects tell you more about someone than any introduction."],
 es:["1. Uno elige 5 objetos para el museo de su vida: no valiosos, pero importantes para él.\n2. Cuenta en breve la historia de cada uno.\n3. El otro elige el objeto del que quiere saber más.\n4. Luego cambiáis.","Los objetos cuentan a una persona mejor que cualquier presentación."]},
"bambini|QUESTO O QUELLO — VERSIONE SERIA":{
 it:["1. Uno propone un dilemma serio (es. «Sicurezza o libertà?»).\n2. Al tre, scegliete insieme: mano alzata per la prima, giù per la seconda.\n3. Ognuno spiega il perché in 30 secondi.","Non c'è una risposta giusta: è il bello del gioco."],
 en:["1. One suggests a serious dilemma (e.g. \"Security or freedom?\").\n2. On three, choose together: hand up for the first, down for the second.\n3. Each explains why in 30 seconds.","There's no right answer: that's the fun of it."],
 es:["1. Uno propone un dilema serio (p. ej. «¿Seguridad o libertad?»).\n2. A la de tres, elegid a la vez: mano arriba para la primera, abajo para la segunda.\n3. Cada uno explica por qué en 30 segundos.","No hay respuesta correcta: eso es lo bonito."]},
"bambini|LE DOMANDE CHE CONTANO":{
 it:["Tre giri di domande, sempre più profondi.\n1. Leggero: cosa ti fa ridere davvero? Il tuo posto preferito?\n2. Medio: cosa ti spaventa del futuro? Di cosa vai fiero?\n3. Profondo: cosa cerchi in una persona? Cosa vorresti che capissero di te?\nRispondete a turno.","Non saltate il giro leggero: serve a scaldarsi."],
 en:["Three rounds of questions, each deeper.\n1. Light: what really makes you laugh? Your favourite place?\n2. Medium: what scares you about the future? What are you proud of?\n3. Deep: what do you look for in someone? What do you wish people understood about you?\nAnswer in turn.","Don't skip the light round: it's the warm-up."],
 es:["Tres rondas de preguntas, cada vez más profundas.\n1. Ligera: ¿qué te hace reír de verdad? ¿Tu sitio favorito?\n2. Media: ¿qué te da miedo del futuro? ¿De qué estás orgulloso?\n3. Profunda: ¿qué buscas en una persona? ¿Qué te gustaría que entendieran de ti?\nResponded por turnos.","No os saltéis la ronda ligera: sirve para entrar en calor."]},
"bambini|IL COMPLIMENTO CHE NON HO ANCORA FATTO":{
 it:["1. Uno fa all'altro 3 complimenti precisi, su cose notate oggi.\n2. Non «sei simpatico», ma «mi piace come racconti le cose».\n3. L'altro ascolta fino alla fine. Poi si scambiano.","Un complimento preciso resta in mente per giorni."],
 en:["1. One gives the other 3 specific compliments about things noticed today.\n2. Not \"you're nice\", but \"I like how you tell stories\".\n3. The other listens to the end. Then swap.","A specific compliment stays with you for days."],
 es:["1. Uno le hace al otro 3 cumplidos concretos sobre cosas que ha notado hoy.\n2. No «eres simpático», sino «me gusta cómo cuentas las cosas».\n3. El otro escucha hasta el final. Luego cambiáis.","Un cumplido concreto se recuerda durante días."]},
// ───────────── AZIONE ─────────────
"azione|FREEZE!":{
 it:["1. Due giocatori improvvisano una scena qualsiasi (es. due cuochi).\n2. Chiunque può urlare «FREEZE!»: i due si bloccano nella posa.\n3. Chi ha urlato prende il posto di uno dei due, nella stessa posa.\n4. Inizia una scena completamente nuova.","Più la nuova scena è assurda rispetto alla posa, più si ride."],
 en:["1. Two players improvise any scene (e.g. two chefs).\n2. Anyone can shout \"FREEZE!\": the two stop in their pose.\n3. Whoever shouted takes the place of one of them, in the same pose.\n4. A brand-new scene begins.","The more absurd the new scene is for that pose, the funnier."],
 es:["1. Dos jugadores improvisan una escena cualquiera (p. ej. dos cocineros).\n2. Cualquiera puede gritar «¡FREEZE!»: los dos se quedan quietos en su postura.\n3. Quien gritó ocupa el sitio de uno de ellos, en la misma postura.\n4. Empieza una escena totalmente nueva.","Cuanto más absurda sea la nueva escena para esa postura, más risas."]},
"azione|CONTARE FINO A 21":{
 it:["1. Il gruppo conta da 1 a 21, un numero alla volta.\n2. Nessun ordine fisso: chiunque può dire il numero dopo.\n3. Se due persone parlano insieme, si riparte da 1.\n4. Chi dice 21 inventa una nuova regola (es. «al posto del 7 si batte le mani»).","Guardatevi negli occhi: aiuta più di quanto sembri."],
 en:["1. The group counts from 1 to 21, one number at a time.\n2. No set order: anyone can say the next number.\n3. If two people speak at once, start again from 1.\n4. Whoever says 21 adds a new rule (e.g. \"clap instead of saying 7\").","Look each other in the eye: it helps more than you'd think."],
 es:["1. El grupo cuenta del 1 al 21, un número cada vez.\n2. Sin orden fijo: cualquiera puede decir el siguiente.\n3. Si dos personas hablan a la vez, se vuelve a empezar desde 1.\n4. Quien dice 21 añade una regla nueva (p. ej. «en vez del 7 se da una palmada»).","Miraos a los ojos: ayuda más de lo que parece."]},
"azione|IL MIMO":{
 it:["1. Dividetevi in squadre.\n2. Chi mima tocca «Mostra il titolo» senza farlo vedere: è un film, una canzone o un libro.\n3. Toccate «Inizia il mimo»: la squadra ha 3 minuti per indovinare.\n4. Niente parole, suoni o oggetti indicati. Se indovinano, toccate «Indovinato!».","Prima di iniziare, mostrate con le dita quante parole ha il titolo."],
 en:["1. Split into teams.\n2. The mimer taps \"Show the title\" without letting anyone see: it's a film, a song or a book.\n3. Tap \"Start miming\": the team has 3 minutes to guess.\n4. No words, sounds or pointing at objects. If they get it, tap \"Guessed!\".","Before starting, show with your fingers how many words the title has."],
 es:["1. Dividíos en equipos.\n2. Quien hace la mímica toca «Mostrar el título» sin que nadie lo vea: es una película, una canción o un libro.\n3. Tocad «Empezar la mímica»: el equipo tiene 3 minutos para adivinarlo.\n4. Nada de palabras, sonidos ni señalar objetos. Si aciertan, tocad «¡Adivinado!».","Antes de empezar, indicad con los dedos cuántas palabras tiene el título."]},
"azione|SCULTURA UMANA":{
 it:["1. Uno fa lo scultore e guarda la scena segreta («Mostra la scena»).\n2. Sistema gli altri come statue per rappresentarla, senza parlare.\n3. Toccate «Inizia il timer»: il pubblico ha 1 minuto per indovinare.\n4. Le statue non si muovono e non parlano.","Lo scultore usa solo le mani: niente spiegazioni."],
 en:["1. One player is the sculptor and looks at the secret scene (\"Show the scene\").\n2. They pose the others like statues to show it, without talking.\n3. Tap \"Start the timer\": the audience has 1 minute to guess.\n4. Statues don't move or talk.","The sculptor only uses their hands: no explaining."],
 es:["1. Uno hace de escultor y mira la escena secreta («Mostrar la escena»).\n2. Coloca a los demás como estatuas para representarla, sin hablar.\n3. Tocad «Iniciar el temporizador»: el público tiene 1 minuto para adivinarla.\n4. Las estatuas no se mueven ni hablan.","El escultor solo usa las manos: nada de explicaciones."]},
"azione|IL NODO UMANO":{
 it:["1. In piedi in cerchio, ognuno prende le mani di due persone non vicine.\n2. Ora siete un nodo.\n3. Scioglietelo tutti insieme, senza mai lasciare le mani.","Parlarsi ad alta voce conta più della forza."],
 en:["1. Standing in a circle, everyone takes the hands of two people not next to them.\n2. Now you're a knot.\n3. Untangle it together, without ever letting go.","Talking out loud matters more than strength."],
 es:["1. De pie en círculo, cada uno coge las manos de dos personas que no tenga al lado.\n2. Ahora sois un nudo.\n3. Deshacedlo todos juntos, sin soltaros nunca.","Hablar en voz alta importa más que la fuerza."]},
"azione|SPECCHIO":{
 it:["1. In coppia, uno di fronte all'altro.\n2. Toccate «Inizia il turno»: uno guida, l'altro copia ogni movimento come uno specchio.\n3. Dopo 2 minuti si scambiano i ruoli.\nIl tavolo vota la coppia più sincronizzata.","Chi guida si muove piano: più va lento, più sembrate uno specchio."],
 en:["1. In pairs, facing each other.\n2. Tap \"Start the turn\": one leads, the other copies every move like a mirror.\n3. After 2 minutes, swap roles.\nThe table votes for the most in-sync pair.","Leader, move slowly: the slower, the more mirror-like."],
 es:["1. En parejas, uno frente al otro.\n2. Tocad «Empezar el turno»: uno guía y el otro copia cada movimiento como un espejo.\n3. A los 2 minutos se cambian los papeles.\nLa mesa vota la pareja más sincronizada.","Quien guía se mueve despacio: cuanto más lento, más parecéis un espejo."]},
"azione|IL DOPPIATORE":{
 it:["1. Due giocatori recitano una scena in silenzio (es. una visita dal medico).\n2. Altri due, di spalle e senza guardare, inventano le battute ad alta voce.\n3. Gli attori devono seguire quello che dicono i doppiatori.","Più le battute sono assurde, più si ride."],
 en:["1. Two players act out a scene in silence (e.g. a doctor's visit).\n2. Two others, facing away and not looking, make up the lines out loud.\n3. The actors must follow whatever the voice actors say.","The more absurd the lines, the bigger the laugh."],
 es:["1. Dos jugadores representan una escena en silencio (p. ej. una visita al médico).\n2. Otros dos, de espaldas y sin mirar, inventan los diálogos en voz alta.\n3. Los actores tienen que seguir lo que dicen los dobladores.","Cuanto más absurdos los diálogos, más risas."]},
"azione|TOUCH BLUE":{
 it:["1. Uno grida: «Tocca qualcosa di…» (blu, metallico, morbido…).\n2. Tutti corrono a toccarlo il più in fretta possibile.\n3. L'ultimo prende un punto.\nVince chi alla fine ha meno punti.","Funziona meglio dove ci sono tanti oggetti intorno."],
 en:["1. Someone shouts: \"Touch something…\" (blue, metal, soft…).\n2. Everyone rushes to touch it as fast as possible.\n3. The last one gets a point.\nFewest points at the end wins.","Works best where there are lots of things around."],
 es:["1. Alguien grita: «Toca algo…» (azul, metálico, blando…).\n2. Todos corren a tocarlo lo más rápido posible.\n3. El último se lleva un punto.\nGana quien tenga menos puntos al final.","Funciona mejor donde hay muchos objetos alrededor."]},
"azione|IL ROBOT":{
 it:["1. In coppia: uno è il robot, l'altro il programmatore.\n2. Toccate «Inizia il turno»: il programmatore dà ordini precisi («tre passi avanti», «alza il braccio sinistro»).\n3. Il robot esegue alla lettera, senza pensare.\n4. Dopo 2 minuti si scambiano.","Il robot non interpreta: se l'ordine è sbagliato, lo fa sbagliato."],
 en:["1. In pairs: one is the robot, the other the programmer.\n2. Tap \"Start the turn\": the programmer gives precise orders (\"three steps forward\", \"raise your left arm\").\n3. The robot obeys literally, without thinking.\n4. After 2 minutes, swap.","The robot doesn't interpret: a wrong order gets done wrong."],
 es:["1. En parejas: uno es el robot y el otro el programador.\n2. Tocad «Empezar el turno»: el programador da órdenes precisas («tres pasos adelante», «levanta el brazo izquierdo»).\n3. El robot obedece al pie de la letra, sin pensar.\n4. A los 2 minutos se cambian.","El robot no interpreta: si la orden está mal, la hace mal."]},
"azione|EFFETTO DOMINO":{
 it:["1. Il primo fa un gesto (es. si gratta il naso).\n2. Il secondo rifà quel gesto e ne aggiunge uno suo.\n3. Ognuno rifà tutti i gesti di prima, in ordine, e ne aggiunge uno.\n4. Chi sbaglia è fuori.\nVince l'ultimo rimasto.","Gesti esagerati si ricordano meglio."],
 en:["1. The first makes a gesture (e.g. scratches their nose).\n2. The second repeats it and adds one of their own.\n3. Everyone repeats all the gestures so far, in order, and adds one.\n4. Get it wrong and you're out.\nLast one standing wins.","Over-the-top gestures are easier to remember."],
 es:["1. El primero hace un gesto (p. ej. se rasca la nariz).\n2. El segundo lo repite y añade uno suyo.\n3. Cada uno repite todos los gestos anteriores, en orden, y añade uno.\n4. Quien falla queda fuera.\nGana el último que quede.","Los gestos exagerados se recuerdan mejor."]},
"azione|CACCIA ALL'OGGETTO":{
 it:["1. Scrivete quanti siete e i vostri nomi.\n2. L'app estrae una lettera. Toccate «Via!»: avete 30 secondi.\n3. Trovate un oggetto che inizia con quella lettera e portatelo al tavolo.\n4. Il primo prende il punto (toccate il suo nome).\nVince il primo che arriva a 5 punti.","Gli oggetti più strani fanno ridere di più."],
 en:["1. Enter how many you are and your names.\n2. The app draws a letter. Tap \"Go!\": you have 30 seconds.\n3. Find an object starting with that letter and bring it to the table.\n4. The first one gets the point (tap their name).\nFirst to 5 points wins.","The weirder the object, the bigger the laugh."],
 es:["1. Poned cuántos sois y vuestros nombres.\n2. La app saca una letra. Tocad «¡Ya!»: tenéis 30 segundos.\n3. Encontrad un objeto que empiece por esa letra y traedlo a la mesa.\n4. El primero gana el punto (tocad su nombre).\nGana el primero que llegue a 5 puntos.","Cuanto más raro el objeto, más risas."]},
// ───────────── CREATIVI ─────────────
"creativi|FRASE PER FRASE":{
 it:["1. Inventate una storia tutti insieme.\n2. A turno, ognuno aggiunge solo 3 parole.\n3. Andate veloci, senza pensarci troppo.","Non cercate di controllare la storia: più è assurda, meglio è."],
 en:["1. Make up a story all together.\n2. In turn, each player adds only 3 words.\n3. Go fast, without thinking too much.","Don't try to steer it: the more absurd, the better."],
 es:["1. Inventad una historia entre todos.\n2. Por turnos, cada uno añade solo 3 palabras.\n3. Id rápido, sin pensarlo mucho.","No intentéis controlar la historia: cuanto más absurda, mejor."]},
"creativi|PUBBLICITÀ ASSURDA":{
 it:["1. L'app ti dà un prodotto assurdo (puoi cambiarlo con «Altro prodotto»).\n2. Tocca «Inizia lo spot»: hai 2 minuti.\n3. Presentalo come una pubblicità vera: nome, slogan e perché comprarlo.\n4. Poi tocca al prossimo.\nAlla fine votate lo spot migliore.","Più ci credi, più fa ridere: sei in diretta TV."],
 en:["1. The app gives you an absurd product (you can change it with \"Another product\").\n2. Tap \"Start the ad\": you have 2 minutes.\n3. Pitch it like a real ad: name, slogan and why to buy it.\n4. Then it's the next player's turn.\nAt the end, vote for the best ad.","The more you believe it, the funnier it is: you're live on TV."],
 es:["1. La app te da un producto absurdo (puedes cambiarlo con «Otro producto»).\n2. Toca «Empezar el anuncio»: tienes 2 minutos.\n3. Preséntalo como un anuncio real: nombre, eslogan y por qué comprarlo.\n4. Luego le toca al siguiente.\nAl final votad el mejor anuncio.","Cuanto más te lo creas, más gracia tiene: estás en directo."]},
"creativi|STORIA COLLETTIVA":{
 it:["1. Il primo dice una frase per iniziare una storia.\n2. A turno, ognuno aggiunge una frase.\n3. Non si può contraddire quello che è già stato detto.","Un colpo di scena a testa rende la storia esplosiva."],
 en:["1. The first player says a sentence to start a story.\n2. In turn, everyone adds one sentence.\n3. You can't contradict what's already been said.","One plot twist each makes the story explode."],
 es:["1. El primero dice una frase para empezar una historia.\n2. Por turnos, cada uno añade una frase.\n3. No se puede contradecir lo que ya se ha dicho.","Un giro de guion por persona hace la historia explosiva."]},
"creativi|CADAVERE SQUISITO":{
 it:["Servono un foglio e una penna.\n1. Il primo scrive una frase, poi piega il foglio lasciando vedere solo l'ultima parola.\n2. Il prossimo continua da quella parola, piega e passa.\n3. Alla fine aprite il foglio e leggete tutto ad alta voce.","Si può fare anche disegnando: si lascia vedere solo l'ultimo pezzo del disegno."],
 en:["You need a sheet of paper and a pen.\n1. The first writes a sentence, then folds the paper so only the last word shows.\n2. The next continues from that word, folds and passes it on.\n3. At the end, unfold it and read everything out loud.","You can also play drawing: only the last bit of the drawing is left showing."],
 es:["Hacen falta una hoja y un bolígrafo.\n1. El primero escribe una frase y dobla la hoja dejando ver solo la última palabra.\n2. El siguiente sigue desde esa palabra, dobla y la pasa.\n3. Al final desdoblad la hoja y leedlo todo en voz alta.","También se puede jugar dibujando: solo se deja ver el último trozo del dibujo."]},
"creativi|ALIENO A TAVOLA":{
 it:["1. Uno fa l'alieno: non conosce niente della Terra.\n2. Gli altri gli spiegano gli oggetti sul tavolo (bicchiere, telefono…) senza mai dirne il nome.\n3. L'alieno fa domande ingenue: «A cosa serve?», «Perché?».\n4. Chi dice il nome dell'oggetto paga pegno.","Più l'alieno è ingenuo, più mette in difficoltà gli altri."],
 en:["1. One player is the alien: they know nothing about Earth.\n2. The others explain the objects on the table (glass, phone…) without ever saying their names.\n3. The alien asks naive questions: \"What's it for?\", \"Why?\".\n4. Whoever says the object's name pays a forfeit.","The more naive the alien, the harder it gets for everyone."],
 es:["1. Uno hace de alienígena: no sabe nada de la Tierra.\n2. Los demás le explican los objetos de la mesa (vaso, móvil…) sin decir nunca su nombre.\n3. El alienígena hace preguntas ingenuas: «¿Para qué sirve?», «¿Por qué?».\n4. Quien diga el nombre del objeto paga prenda.","Cuanto más ingenuo el alienígena, más difícil para los demás."]},
// ───────────── CULTURA ─────────────
"cultura|ANNO GIUSTO":{
 p:"1-8",
 it:["1. Scrivete quanti siete e i vostri nomi.\n2. L'app mostra un evento storico o un'invenzione.\n3. A turno, ognuno sceglie l'anno con il cursore e i tasti ±, poi «Conferma risposta».\n4. Chi si avvicina di più prende un punto.\n10 domande. Se c'è parità, altre 3 domande finché uno vince.\nDa soli: punto se sbagli di 10 anni al massimo.","Le invenzioni sono spesso molto più antiche di quanto si pensi."],
 en:["1. Enter how many you are and your names.\n2. The app shows a historical event or an invention.\n3. Taking turns, everyone picks the year with the slider and the ± buttons, then \"Confirm answer\".\n4. Closest gets a point.\n10 questions. If there's a tie, 3 more questions until someone wins.\nAlone: a point if you're within 10 years.","Inventions are often much older than you'd think."],
 es:["1. Poned cuántos sois y vuestros nombres.\n2. La app muestra un hecho histórico o un invento.\n3. Por turnos, cada uno elige el año con el deslizador y los botones ±, y luego «Confirmar respuesta».\n4. Quien más se acerque gana un punto.\n10 preguntas. Si hay empate, 3 preguntas más hasta que gane uno.\nSolo: punto si fallas por 10 años como mucho.","Los inventos suelen ser mucho más antiguos de lo que parece."]},
"cultura|PRIMA O DOPO?":{
 p:"1-10",
 it:["1. Scegliete quanti siete e il livello.\n2. L'app mostra due eventi: dite ad alta voce quale è venuto prima.\n3. Toccate «Rivela la risposta».\n4. Chi ha indovinato tocca il suo nome e prende un punto.\n10 domande. Se c'è parità, altre 3 domande finché uno vince.","Pensate a cosa c'era intorno a quell'epoca: aiuta a ordinare."],
 en:["1. Choose how many you are and the level.\n2. The app shows two events: say out loud which came first.\n3. Tap \"Reveal answer\".\n4. Whoever got it right taps their name and scores a point.\n10 questions. If there's a tie, 3 more until someone wins.","Think about what else was around at the time: it helps."],
 es:["1. Elegid cuántos sois y el nivel.\n2. La app muestra dos hechos: decid en voz alta cuál fue antes.\n3. Tocad «Revelar respuesta».\n4. Quien acertó toca su nombre y gana un punto.\n10 preguntas. Si hay empate, 3 más hasta que gane uno.","Pensad en qué más había en esa época: ayuda a ordenarlos."]},
"cultura|CHE BANDIERA È?":{
 p:"1-10",
 it:["1. Scegliete quanti siete e il livello.\n2. L'app mostra una bandiera.\n3. A turno, ognuno sceglie il paese giusto tra 4, senza farsi vedere.\n4. Poi si scopre la risposta.\n10 bandiere: un punto per ogni risposta giusta. Se c'è parità, altre 3 finché uno vince.","Le bandiere più simili tra loro sono le più difficili!"],
 en:["1. Choose how many you are and the level.\n2. The app shows a flag.\n3. Taking turns, everyone picks the right country out of 4, without showing the others.\n4. Then the answer is revealed.\n10 flags: one point per right answer. If there's a tie, 3 more until someone wins.","The flags that look alike are the hardest!"],
 es:["1. Elegid cuántos sois y el nivel.\n2. La app muestra una bandera.\n3. Por turnos, cada uno elige el país correcto entre 4, sin que los demás lo vean.\n4. Luego se ve la respuesta.\n10 banderas: un punto por acierto. Si hay empate, 3 más hasta que gane uno.","¡Las banderas parecidas son las más difíciles!"]},
"cultura|CHE LINGUA È?":{
 p:"1-10",
 it:["1. Scegliete quanti siete e il livello.\n2. L'app mostra una frase in un'altra lingua.\n3. A turno, ognuno sceglie la lingua giusta tra 4, senza farsi vedere.\n4. Poi si scopre la soluzione, con il paese e il significato.\n10 frasi: un punto per ogni risposta giusta. Se c'è parità, altre 3 frasi finché uno vince.","Guardate le lettere strane e gli accenti: ogni lingua ha i suoi."],
 en:["1. Choose how many you are and the level.\n2. The app shows a sentence in another language.\n3. Taking turns, everyone picks the right language out of 4, without showing the others.\n4. Then the answer appears, with the country and the meaning.\n10 sentences: one point per right answer. If there's a tie, 3 more sentences until someone wins.","Look at the odd letters and accents: every language has its own."],
 es:["1. Elegid cuántos sois y el nivel.\n2. La app muestra una frase en otro idioma.\n3. Por turnos, cada uno elige el idioma correcto entre 4, sin que los demás lo vean.\n4. Luego sale la solución, con el país y el significado.\n10 frases: un punto por acierto. Si hay empate, 3 frases más hasta que gane uno.","Fijaos en las letras raras y los acentos: cada idioma tiene los suyos."]},
"cultura|VERO O FALSO? SCIENTIFICO":{
 p:"1-10",
 it:["1. Scegliete quanti siete e il livello.\n2. L'app mostra un fatto scientifico: dite ad alta voce se è vero o falso.\n3. Toccate «Rivela la risposta».\n4. Chi ha indovinato tocca il suo nome e prende un punto.\n10 domande. Se c'è parità, altre 3 domande finché uno vince.","I falsi più convincenti sono quelli che sembrano logici."],
 en:["1. Choose how many you are and the level.\n2. The app shows a science fact: say out loud if it's true or false.\n3. Tap \"Reveal answer\".\n4. Whoever got it right taps their name and scores a point.\n10 questions. If there's a tie, 3 more until someone wins.","The most convincing fakes are the ones that sound logical."],
 es:["1. Elegid cuántos sois y el nivel.\n2. La app muestra un dato científico: decid en voz alta si es verdadero o falso.\n3. Tocad «Revelar respuesta».\n4. Quien acertó toca su nombre y gana un punto.\n10 preguntas. Si hay empate, 3 más hasta que gane uno.","Los falsos más convincentes son los que parecen lógicos."]},
"cultura|CHI L'HA INVENTATO?":{
 p:"1-10",
 it:["1. Scegliete quanti siete e il livello.\n2. L'app mostra un'invenzione: dite ad alta voce chi l'ha inventata.\n3. Toccate «Rivela la risposta».\n4. Chi ha indovinato tocca il suo nome e prende un punto.\n10 domande. Se c'è parità, altre 3 domande finché uno vince.","Tante invenzioni famose sono nate per caso."],
 en:["1. Choose how many you are and the level.\n2. The app shows an invention: say out loud who invented it.\n3. Tap \"Reveal answer\".\n4. Whoever got it right taps their name and scores a point.\n10 questions. If there's a tie, 3 more until someone wins.","Lots of famous inventions happened by accident."],
 es:["1. Elegid cuántos sois y el nivel.\n2. La app muestra un invento: decid en voz alta quién lo inventó.\n3. Tocad «Revelar respuesta».\n4. Quien acertó toca su nombre y gana un punto.\n10 preguntas. Si hay empate, 3 más hasta que gane uno.","Muchos inventos famosos nacieron por casualidad."]},
"cultura|CAPITALI DEL MONDO":{
 p:"1-10",
 it:["1. Scegliete quanti siete e il livello.\n2. L'app mostra un paese: dite ad alta voce la sua capitale.\n3. Toccate «Rivela la risposta».\n4. Chi ha indovinato tocca il suo nome e prende un punto.\n10 domande. Se c'è parità, altre 3 domande finché uno vince.","Il più veloce a rispondere mette pressione agli altri."],
 en:["1. Choose how many you are and the level.\n2. The app shows a country: say its capital out loud.\n3. Tap \"Reveal answer\".\n4. Whoever got it right taps their name and scores a point.\n10 questions. If there's a tie, 3 more until someone wins.","Answering fast puts pressure on the others."],
 es:["1. Elegid cuántos sois y el nivel.\n2. La app muestra un país: decid en voz alta su capital.\n3. Tocad «Revelar respuesta».\n4. Quien acertó toca su nombre y gana un punto.\n10 preguntas. Si hay empate, 3 más hasta que gane uno.","Responder rápido mete presión a los demás."]},
"cultura|QUIZ DELLE CATEGORIE":{
 p:"1-10",
 it:["1. Scegliete quanti siete e il livello.\n2. L'app dà una categoria (es. «5 tipi di pasta»): ditene più che potete.\n3. Toccate «Rivela la risposta» per vedere degli esempi.\n4. Chi ce l'ha fatta tocca il suo nome e prende un punto.\n10 domande. Se c'è parità, altre 3 domande finché uno vince.","Le categorie che sembrano facili sono le più traditrici."],
 en:["1. Choose how many you are and the level.\n2. The app gives a category (e.g. \"5 types of pasta\"): name as many as you can.\n3. Tap \"Reveal answer\" to see some examples.\n4. Whoever made it taps their name and scores a point.\n10 questions. If there's a tie, 3 more until someone wins.","The categories that look easy are the trickiest."],
 es:["1. Elegid cuántos sois y el nivel.\n2. La app da una categoría (p. ej. «5 tipos de pasta»): decid todos los que podáis.\n3. Tocad «Revelar respuesta» para ver ejemplos.\n4. Quien lo consiguió toca su nombre y gana un punto.\n10 preguntas. Si hay empate, 3 más hasta que gane uno.","Las categorías que parecen fáciles son las más traicioneras."]},
"cultura|QUANTO VALE?":{
 it:["1. Scrivete quanti siete e i vostri nomi.\n2. L'app fa una domanda con un numero (es. «Quante calorie ha un avocado?»).\n3. Passatevi il telefono: ognuno sceglie il suo numero e tocca «Conferma» (40 secondi a testa).\n4. Chi si avvicina di più prende un punto.\n10 domande. Se c'è parità, altre 3 domande finché uno vince.\nPotete anche sfidare un altro tavolo: ognuno gioca dal suo telefono.","Ragionate per difetto o per eccesso: non sparate a caso."],
 en:["1. Enter how many you are and your names.\n2. The app asks a question with a number (e.g. \"How many calories in an avocado?\").\n3. Pass the phone: everyone picks their number and taps \"Confirm\" (40 seconds each).\n4. Closest gets a point.\n10 questions. If there's a tie, 3 more until someone wins.\nYou can also challenge another table: everyone plays on their own phone.","Reason it out: don't just throw out a number."],
 es:["1. Poned cuántos sois y vuestros nombres.\n2. La app hace una pregunta con un número (p. ej. «¿Cuántas calorías tiene un aguacate?»).\n3. Pasaos el móvil: cada uno elige su número y toca «Confirmar» (40 segundos cada uno).\n4. Quien más se acerque gana un punto.\n10 preguntas. Si hay empate, 3 más hasta que gane uno.\nTambién podéis retar a otra mesa: cada uno juega desde su móvil.","Razonadlo: no digáis un número al azar."]},
// ───────────── 18+ ─────────────
"adulti|CHI È PIÙ PROBABILE?":{
 it:["1. Leggete la frase ad alta voce.\n2. Al tre, tutti puntano il dito su qualcuno (non su sé stessi).\n3. Chi ha più dita addosso sceglie: si difende per 30 secondi oppure beve.\n4. Toccate «Prossima frase».","Puntate chi se lo merita, non il più timido."],
 en:["1. Read the line out loud.\n2. On three, everyone points at someone (not themselves).\n3. Whoever gets the most fingers chooses: defend yourself for 30 seconds or drink.\n4. Tap \"Next phrase\".","Point at whoever deserves it, not the shyest one."],
 es:["1. Leed la frase en voz alta.\n2. A la de tres, todos señalan a alguien (no a sí mismos).\n3. Quien reciba más dedos elige: se defiende 30 segundos o bebe.\n4. Tocad «Siguiente frase».","Señalad a quien se lo merece, no al más tímido."]},
"adulti|IL SUSSURRO 18+":{
 it:["1. Chi ha il telefono legge la domanda in silenzio e la sussurra al vicino.\n2. Il vicino risponde ad alta voce solo con un nome del tavolo.\n3. Chi è stato nominato può lanciare una moneta: testa, la domanda si legge a tutti; croce, resta segreta.\n4. Passate il telefono e toccate «Prossima frase».","Rispondete senza ridere e senza esitare."],
 en:["1. Whoever holds the phone reads the question silently and whispers it to their neighbour.\n2. The neighbour answers out loud with just a name from the table.\n3. The person named can flip a coin: heads, the question is read to everyone; tails, it stays secret.\n4. Pass the phone and tap \"Next phrase\".","Answer without laughing and without hesitating."],
 es:["1. Quien tiene el móvil lee la pregunta en silencio y se la susurra al de al lado.\n2. Este responde en voz alta solo con un nombre de la mesa.\n3. La persona nombrada puede lanzar una moneda: cara, la pregunta se lee a todos; cruz, queda en secreto.\n4. Pasad el móvil y tocad «Siguiente frase».","Responded sin reír y sin dudar."]},
"adulti|RISPONDI O BEVI":{
 it:["1. Il gruppo sceglie a chi fare la domanda.\n2. Leggetegliela ad alta voce.\n3. Lui sceglie: risponde sinceramente oppure beve e passa.\n4. Toccate «Prossima frase».","Chi beve senza pensarci ha appena risposto lo stesso."],
 en:["1. The group picks who gets the question.\n2. Read it to them out loud.\n3. They choose: answer honestly, or drink and pass.\n4. Tap \"Next phrase\".","Drinking without a second thought is an answer too."],
 es:["1. El grupo elige a quién hacerle la pregunta.\n2. Leédsela en voz alta.\n3. Elige: responde con sinceridad o bebe y pasa.\n4. Tocad «Siguiente frase».","Beber sin pensarlo también es una respuesta."]},
"adulti|CONFESSIONI ANONIME":{
 it:["1. Scrivete quanti siete.\n2. A turno, di nascosto, ognuno scrive sul telefono una confessione vera (se serve, usa lo spunto).\n3. Toccate «Mescola e inizia»: l'app legge le confessioni una alla volta, in ordine casuale.\n4. Il gruppo vota di chi è.\nChi viene scoperto beve o paga pegno.","Scrivete come scriverebbe qualcun altro: depistare fa parte del gioco."],
 en:["1. Enter how many you are.\n2. Taking turns, secretly, everyone types a true confession on the phone (use the prompt if you need one).\n3. Tap \"Shuffle and start\": the app shows the confessions one at a time, in random order.\n4. The group votes on whose it is.\nWhoever gets caught drinks or pays a forfeit.","Write the way someone else would: misleading is part of the game."],
 es:["1. Poned cuántos sois.\n2. Por turnos, a escondidas, cada uno escribe en el móvil una confesión real (si hace falta, usa la idea).\n3. Tocad «Mezclar y empezar»: la app muestra las confesiones una a una, en orden aleatorio.\n4. El grupo vota de quién es.\nA quien pillen bebe o paga prenda.","Escribid como lo haría otro: despistar es parte del juego."]},
"adulti|IL PROCESSO":{
 it:["1. Leggete l'accusa. Scegliete tre ruoli: imputato, avvocato e accusa.\n2. Un minuto a testa: l'accusa attacca, l'avvocato difende, l'imputato si giustifica.\n3. Il resto del tavolo vota: colpevole o innocente.\nSe è colpevole beve l'imputato, se è innocente beve l'accusa.","Scegliete come imputato chi sembra più innocente."],
 en:["1. Read the charge. Pick three roles: defendant, lawyer and prosecutor.\n2. One minute each: the prosecutor attacks, the lawyer defends, the defendant explains.\n3. The rest of the table votes: guilty or innocent.\nGuilty, the defendant drinks; innocent, the prosecutor drinks.","Pick the most innocent-looking person as the defendant."],
 es:["1. Leed la acusación. Elegid tres papeles: acusado, abogado y fiscal.\n2. Un minuto cada uno: el fiscal ataca, el abogado defiende, el acusado se justifica.\n3. El resto de la mesa vota: culpable o inocente.\nSi es culpable bebe el acusado; si es inocente, bebe el fiscal.","Elegid como acusado a quien parezca más inocente."]},
"adulti|L'EX":{
 it:["1. Leggete il tema (potete cambiarlo con «Cambia domanda»).\n2. Chi racconta tocca «Inizia»: ha 2 minuti per una storia vera sul suo ex.\n3. Niente nomi veri, solo soprannomi.\n4. Alla fine votate la storia migliore: chi vince sceglie chi beve.","Le storie migliori sono quelle in cui chi racconta non ne esce benissimo."],
 en:["1. Read the topic (you can change it with \"Another one\").\n2. The storyteller taps \"Start\": they get 2 minutes for a true story about their ex.\n3. No real names, nicknames only.\n4. At the end, vote for the best story: the winner chooses who drinks.","The best stories are the ones where the teller doesn't come off great."],
 es:["1. Leed el tema (podéis cambiarlo con «Otra pregunta»).\n2. Quien cuenta toca «Empezar»: tiene 2 minutos para una historia real sobre su ex.\n3. Nada de nombres reales, solo apodos.\n4. Al final votad la mejor historia: quien gane elige quién bebe.","Las mejores historias son aquellas en las que quien cuenta no queda muy bien."]},
"adulti|SCALA PICCANTE":{
 it:["1. Leggete la situazione.\n2. Al tre, tutti alzano da 1 a 5 dita: 1 = mai nella vita, 5 = già fatto e lo rifarei.\n3. Chi ha alzato meno dita e chi ne ha alzate di più si spiegano in 30 secondi.\n4. Toccate «Prossima frase».","Un 3 detto con troppa calma di solito è un 5."],
 en:["1. Read the situation.\n2. On three, everyone raises 1 to 5 fingers: 1 = never ever, 5 = done it and would again.\n3. The lowest and the highest explain themselves in 30 seconds.\n4. Tap \"Next phrase\".","A 3 said too calmly is usually a 5."],
 es:["1. Leed la situación.\n2. A la de tres, todos levantan de 1 a 5 dedos: 1 = jamás, 5 = ya lo hice y lo repetiría.\n3. Quien levantó menos dedos y quien levantó más se explican en 30 segundos.\n4. Tocad «Siguiente frase».","Un 3 dicho con demasiada calma suele ser un 5."]},
"adulti|CHI SEI DAVVERO? (18+)":{
 it:["1. Leggete il dilemma: due risposte, niente vie di mezzo.\n2. Toccate «Inizia il round» e, al tre, scegliete: mano alzata per la prima, giù per la seconda.\n3. Chi è in minoranza ha 20 secondi per difendersi.\nSe vi dividete esattamente a metà, bevono tutti.","Non pensateci: la prima risposta è quella vera."],
 en:["1. Read the dilemma: two answers, no middle ground.\n2. Tap \"Start the round\" and, on three, choose: hand up for the first, down for the second.\n3. The minority gets 20 seconds to defend themselves.\nIf you split exactly in half, everyone drinks.","Don't think: your first answer is the true one."],
 es:["1. Leed el dilema: dos respuestas, sin término medio.\n2. Tocad «Empezar la ronda» y, a la de tres, elegid: mano arriba para la primera, abajo para la segunda.\n3. Quien quede en minoría tiene 20 segundos para defenderse.\nSi os dividís justo por la mitad, bebéis todos.","No lo penséis: la primera respuesta es la verdadera."]},
"adulti|OPINIONI SCOTTANTI 18+":{
 it:["1. Leggete l'opinione.\n2. Al tre: pollice su se siete d'accordo, giù se no.\n3. La minoranza ha 30 secondi per convincere gli altri.\nSe almeno uno cambia idea, beve la maggioranza.","Non serve crederci: serve difenderla bene."],
 en:["1. Read the opinion.\n2. On three: thumbs up if you agree, down if you don't.\n3. The minority gets 30 seconds to convince the others.\nIf at least one person changes their mind, the majority drinks.","You don't have to believe it: just defend it well."],
 es:["1. Leed la opinión.\n2. A la de tres: pulgar arriba si estáis de acuerdo, abajo si no.\n3. La minoría tiene 30 segundos para convencer a los demás.\nSi al menos uno cambia de opinión, bebe la mayoría.","No hace falta creérsela: hace falta defenderla bien."]},
"adulti|IMBARAZZOMETRO":{
 it:["1. Leggete il tema.\n2. Chi vuole racconta la sua storia più imbarazzante su quel tema.\n3. Gli altri votano con le dita da 1 a 10.\nChi prende il voto più alto vince il giro e sceglie chi beve.","I dettagli fanno il punteggio: dove eri, cosa hai detto esattamente."],
 en:["1. Read the topic.\n2. Whoever wants to tells their most embarrassing story on that topic.\n3. The others vote with their fingers from 1 to 10.\nHighest score wins the round and chooses who drinks.","Details make the score: where you were, exactly what you said."],
 es:["1. Leed el tema.\n2. Quien quiera cuenta su historia más vergonzosa sobre ese tema.\n3. Los demás votan con los dedos del 1 al 10.\nQuien saque la nota más alta gana la ronda y elige quién bebe.","Los detalles dan la nota: dónde estabas, qué dijiste exactamente."]},
"adulti|PRIMI E ULTIMI":{
 it:["1. Leggete la frase: una «prima volta» o un'«ultima volta».\n2. Tutti rispondono a turno, in poche parole.\n3. Chi non vuole rispondere beve.\n4. Toccate «Prossima frase».","Le risposte più corte sono le più pericolose."],
 en:["1. Read the line: a \"first time\" or a \"last time\".\n2. Everyone answers in turn, in a few words.\n3. Anyone who won't answer drinks.\n4. Tap \"Next phrase\".","The shortest answers are the most dangerous."],
 es:["1. Leed la frase: una «primera vez» o una «última vez».\n2. Todos responden por turnos, en pocas palabras.\n3. Quien no quiera responder bebe.\n4. Tocad «Siguiente frase».","Las respuestas más cortas son las más peligrosas."]},
"adulti|NON HO MAI (18+)":{
 it:["1. Tutti iniziano con 5 dita alzate.\n2. Leggete la frase «Non ho mai…».\n3. Chi invece l'ha fatto abbassa un dito e beve un sorso.\n4. Toccate «Prossima frase».\nChi resta senza dita paga pegno.","Guardate le facce, non solo le dita."],
 en:["1. Everyone starts with 5 fingers up.\n2. Read the \"Never have I ever…\" line.\n3. Whoever has done it puts a finger down and takes a sip.\n4. Tap \"Next phrase\".\nWhoever runs out of fingers pays a forfeit.","Watch the faces, not just the fingers."],
 es:["1. Todos empiezan con 5 dedos levantados.\n2. Leed la frase «Yo nunca…».\n3. Quien sí lo ha hecho baja un dedo y bebe un sorbo.\n4. Tocad «Siguiente frase».\nQuien se quede sin dedos paga prenda.","Mirad las caras, no solo los dedos."]},
// ───────────── A DISTANZA ─────────────
"relax|INDOVINA IL CODICE":{
 it:["1. Ognuno sceglie un codice segreto di 4 cifre.\n2. Al tuo turno prova a indovinare il codice di un avversario.\nVerde = cifra giusta al posto giusto. Giallo = cifra giusta al posto sbagliato.\nVince chi indovina per primo un codice.","Guardate anche i tentativi degli altri: ogni risposta è un indizio."],
 en:["1. Everyone picks a secret 4-digit code.\n2. On your turn, try to crack an opponent's code.\nGreen = right digit, right place. Yellow = right digit, wrong place.\nFirst to crack a code wins.","Watch the others' tries too: every answer is a clue."],
 es:["1. Cada uno elige un código secreto de 4 cifras.\n2. En tu turno intenta adivinar el código de un rival.\nVerde = cifra correcta en su sitio. Amarillo = cifra correcta en otro sitio.\nGana quien adivine primero un código.","Mirad también los intentos de los demás: cada respuesta es una pista."]},
"relax|ANNO GIUSTO":{
 it:["1. L'app mostra un evento: scegli l'anno con il cursore e i tasti ±. Hai 30 secondi.\n2. Chi si avvicina di più prende un punto.\n10 domande. Se c'è parità in testa, 3 domande di spareggio.","Le invenzioni sono spesso molto più antiche di quanto si pensi."],
 en:["1. The app shows an event: pick the year with the slider and the ± buttons. You have 30 seconds.\n2. Closest gets a point.\n10 questions. If there's a tie at the top, 3 tie-break questions.","Inventions are often much older than you'd think."],
 es:["1. La app muestra un hecho: elige el año con el deslizador y los botones ±. Tienes 30 segundos.\n2. Quien más se acerque gana un punto.\n10 preguntas. Si hay empate en cabeza, 3 preguntas de desempate.","Los inventos suelen ser mucho más antiguos de lo que parece."]},
"relax|PRIMA O DOPO?":{
 it:["1. L'app mostra due eventi: rispondi se il primo è venuto prima, dopo o nello stesso periodo. Hai 30 secondi.\n2. Ogni risposta giusta vale un punto.\n10 domande. Se c'è parità in testa, 3 domande di spareggio.","Pensate a cosa c'era intorno a quell'epoca: aiuta a ordinare."],
 en:["1. The app shows two events: answer whether the first came before, after or around the same time. You have 30 seconds.\n2. Each right answer is a point.\n10 questions. If there's a tie at the top, 3 tie-break questions.","Think about what else was around at the time: it helps."],
 es:["1. La app muestra dos hechos: responde si el primero fue antes, después o en la misma época. Tienes 30 segundos.\n2. Cada acierto vale un punto.\n10 preguntas. Si hay empate en cabeza, 3 preguntas de desempate.","Pensad en qué más había en esa época: ayuda a ordenarlos."]},
"relax|CHE BANDIERA È?":{
 it:["1. L'app mostra una bandiera: scegli il paese giusto tra 4. Hai 30 secondi.\n2. Ogni risposta giusta vale un punto.\n10 bandiere. Se c'è parità in testa, 3 bandiere di spareggio.","Le bandiere più simili tra loro sono le più difficili!"],
 en:["1. The app shows a flag: pick the right country out of 4. You have 30 seconds.\n2. Each right answer is a point.\n10 flags. If there's a tie at the top, 3 tie-break flags.","The flags that look alike are the hardest!"],
 es:["1. La app muestra una bandera: elige el país correcto entre 4. Tienes 30 segundos.\n2. Cada acierto vale un punto.\n10 banderas. Si hay empate en cabeza, 3 banderas de desempate.","¡Las banderas parecidas son las más difíciles!"]},
"relax|CHE LINGUA È?":{
 it:["1. L'app mostra una frase in un'altra lingua: scegli la lingua giusta tra 4. Hai 30 secondi.\n2. Ogni risposta giusta vale un punto. Poi vedete il paese e il significato.\n10 frasi. Se c'è parità in testa, altre 3 frasi finché uno vince.","Guardate le lettere strane e gli accenti: ogni lingua ha i suoi."],
 en:["1. The app shows a sentence in another language: pick the right language out of 4. You have 30 seconds.\n2. Each right answer is a point. Then you see the country and the meaning.\n10 sentences. If there's a tie at the top, 3 more sentences until someone wins.","Look at the odd letters and accents: every language has its own."],
 es:["1. La app muestra una frase en otro idioma: elige el idioma correcto entre 4. Tienes 30 segundos.\n2. Cada acierto vale un punto. Luego veis el país y el significado.\n10 frases. Si hay empate en cabeza, 3 frases más hasta que gane uno.","Fijaos en las letras raras y los acentos: cada idioma tiene los suyos."]},
"relax|QUANTO VALE?":{
 it:["1. L'app fa una domanda con un numero: scegli la tua risposta con il cursore e i tasti ±. Hai 30 secondi.\n2. Chi si avvicina di più prende un punto.\n10 domande. Se c'è parità in testa, 3 domande di spareggio.","Ragionate per difetto o per eccesso: non sparate a caso."],
 en:["1. The app asks a question with a number: pick your answer with the slider and the ± buttons. You have 30 seconds.\n2. Closest gets a point.\n10 questions. If there's a tie at the top, 3 tie-break questions.","Reason it out: don't just throw out a number."],
 es:["1. La app hace una pregunta con un número: elige tu respuesta con el deslizador y los botones ±. Tienes 30 segundos.\n2. Quien más se acerque gana un punto.\n10 preguntas. Si hay empate en cabeza, 3 preguntas de desempate.","Razonadlo: no digáis un número al azar."]},
"relax|L'OCCHIO DEI COLORI":{
 it:["1. Tutti ricevono le stesse 4 file di colori: mettile in ordine di sfumatura. Hai 3 minuti.\n2. Le strisce col puntino restano ferme.\nVince il più preciso. Se c'è parità, chi è pari rifà una prova più difficile.","Allo scadere dei 3 minuti conta l'ordine che hai fatto fin lì."],
 en:["1. Everyone gets the same 4 rows of colours: sort them by shade. You have 3 minutes.\n2. Stripes with a dot stay put.\nMost precise wins. If there's a tie, the tied players redo a harder round.","When the 3 minutes are up, your order so far is what counts."],
 es:["1. Todos reciben las mismas 4 filas de colores: ordénalas por tono. Tienes 3 minutos.\n2. Las franjas con punto no se mueven.\nGana el más preciso. Si hay empate, los empatados repiten una prueba más difícil.","Al acabar los 3 minutos cuenta el orden que tengas hasta ese momento."]},
"relax|IL TEMPO PERFETTO":{
 it:["1. Chi lancia la sfida fa l'host e non gioca: sceglie un tempo (es. 0:12,345) e fa partire il cronometro.\n2. Gli altri vedono un grande pulsante verde. Quando parte compaiono PRONTI, 3, 2, 1: al rosso il tempo è partito.\n3. Premilo quando pensi di essere arrivato esattamente al tempo scelto, senza vedere il cronometro.\n3 turni: vince chi in totale si avvicina di più. Se c'è parità, si rigioca un turno.","Contate a mente con calma: meglio un ritmo regolare che veloce."],
 en:["1. Whoever sends the challenge is the host and doesn't play: they pick a time (e.g. 0:12.345) and start the stopwatch.\n2. The others see a big green button. When it starts they see READY, 3, 2, 1: on red the clock is running.\n3. Press it when you think you've hit the exact time, without seeing the stopwatch.\n3 rounds: closest overall wins. If there's a tie, one more round.","Count in your head, calmly: a steady rhythm beats a fast one."],
 es:["1. Quien lanza el reto es el anfitrión y no juega: elige un tiempo (p. ej. 0:12,345) y pone en marcha el cronómetro.\n2. Los demás ven un botón verde grande. Cuando empieza aparecen LISTOS, 3, 2, 1: en rojo el tiempo corre.\n3. Púlsalo cuando creas que has llegado justo al tiempo elegido, sin ver el cronómetro.\n3 turnos: gana quien más se acerque en total. Si hay empate, se juega otro turno.","Contad mentalmente con calma: mejor un ritmo regular que rápido."]},
// ───────────── SOLO ─────────────
"solitario|L'OCCHIO DEI COLORI":{
 it:["1. Scegli il livello: più è difficile, più le sfumature sono vicine.\n2. Metti in ordine di sfumatura le 4 file di colori.\n3. Le strisce col puntino restano ferme: sposta le altre trascinandole o toccandole.\nConta solo la precisione.","Guarda la fila da un po' lontano: la striscia fuori posto salta all'occhio."],
 en:["1. Choose the level: the harder it is, the closer the shades.\n2. Sort the 4 rows of colours by shade.\n3. Stripes with a dot stay put: move the others by dragging or tapping.\nOnly precision counts.","Look at the row from a bit further away: the odd one out jumps out."],
 es:["1. Elige el nivel: cuanto más difícil, más parecidos los tonos.\n2. Ordena por tono las 4 filas de colores.\n3. Las franjas con punto no se mueven: mueve las demás arrastrando o tocando.\nSolo cuenta la precisión.","Mira la fila desde un poco más lejos: la que está fuera de sitio salta a la vista."]},
"solitario|DIARIO DEL GIORNO":{
 it:["Pensa a tre cose di oggi:\n1. una che ti ha sorpreso,\n2. una che ti ha dato fastidio,\n3. una che ti ha fatto sorridere.\nScrivile o tienile a mente.","Più dettagli metti, più ti serve."],
 en:["Think of three things from today:\n1. one that surprised you,\n2. one that annoyed you,\n3. one that made you smile.\nWrite them down or keep them in mind.","The more detail, the more useful it is."],
 es:["Piensa en tres cosas de hoy:\n1. una que te sorprendió,\n2. una que te molestó,\n3. una que te hizo sonreír.\nEscríbelas o guárdalas en la cabeza.","Cuantos más detalles, más útil."]},
"solitario|LA MAPPA DEI DESIDERI":{
 it:["1. Pensa a 5 cose che vuoi fare nei prossimi 12 mesi.\n2. Mettile in ordine, dalla più facile alla più difficile.\n3. Scegli una piccola cosa da fare questa settimana per la prima.","Anche un passo piccolo conta."],
 en:["1. Think of 5 things you want to do in the next 12 months.\n2. Put them in order, from easiest to hardest.\n3. Pick one small thing to do this week for the first one.","Even a small step counts."],
 es:["1. Piensa en 5 cosas que quieres hacer en los próximos 12 meses.\n2. Ordénalas, de la más fácil a la más difícil.\n3. Elige algo pequeño que hacer esta semana para la primera.","Hasta un paso pequeño cuenta."]},
"solitario|LETTERA A TE STESSO":{
 it:["1. Scrivi una lettera a te stesso di dieci anni fa.\n2. Cosa gli diresti? Cosa gli consiglieresti di smettere di fare?\n3. Cosa vorresti che sapesse già?","Scrivi di getto, senza correggere."],
 en:["1. Write a letter to yourself ten years ago.\n2. What would you tell them? What would you tell them to stop doing?\n3. What do you wish they already knew?","Write on instinct, without correcting."],
 es:["1. Escribe una carta a ti mismo de hace diez años.\n2. ¿Qué te dirías? ¿Qué te aconsejarías dejar de hacer?\n3. ¿Qué te gustaría que ya supieras?","Escribe del tirón, sin corregir."]},
"solitario|DOMANDE IMPOSSIBILI":{
 it:["1. Scegli una domanda senza risposta giusta (es. «Se potessi rivivere un giorno, quale sceglieresti?»).\n2. Pensaci con calma per 5 minuti.\n3. Poi scrivi la tua risposta.","Non cercare la risposta giusta: cerca la tua."],
 en:["1. Pick a question with no right answer (e.g. \"If you could relive one day, which would it be?\").\n2. Think about it calmly for 5 minutes.\n3. Then write down your answer.","Don't look for the right answer: look for yours."],
 es:["1. Elige una pregunta sin respuesta correcta (p. ej. «Si pudieras revivir un día, ¿cuál elegirías?»).\n2. Piénsalo con calma 5 minutos.\n3. Luego escribe tu respuesta.","No busques la respuesta correcta: busca la tuya."]},
"solitario|GRATITUDINE IN 3":{
 it:["Pensa a tre cose per cui sei grato oggi:\n1. una piccola,\n2. una media,\n3. una grande.\nNessuna è troppo piccola.","Fatto ogni giorno per un mese, cambia il modo di vedere le cose."],
 en:["Think of three things you're grateful for today:\n1. a small one,\n2. a medium one,\n3. a big one.\nNone is too small.","Done every day for a month, it changes how you see things."],
 es:["Piensa en tres cosas por las que estás agradecido hoy:\n1. una pequeña,\n2. una mediana,\n3. una grande.\nNinguna es demasiado pequeña.","Hecho cada día durante un mes, cambia tu forma de ver las cosas."]},
"solitario|SVUOTA LA TESTA":{
 it:["1. Per 5 minuti scrivi tutto quello che ti passa per la testa, senza filtri.\n2. Aspetta 2 minuti.\n3. Rileggi e cerchia la cosa più importante.","Funziona quando hai troppi pensieri e non sai da dove partire."],
 en:["1. For 5 minutes, write everything that goes through your head, no filter.\n2. Wait 2 minutes.\n3. Read it back and circle the most important thing.","It works when you've got too much on your mind and don't know where to start."],
 es:["1. Durante 5 minutos escribe todo lo que se te pase por la cabeza, sin filtro.\n2. Espera 2 minutos.\n3. Reléelo y rodea lo más importante.","Funciona cuando tienes demasiadas cosas en la cabeza y no sabes por dónde empezar."]},
"solitario|IL TEMPO STIMATO":{
 it:["1. Pensa a tre cose che devi fare.\n2. Stima quanto tempo ti serve per ognuna.\n3. Falle e misura il tempo vero.\nConfronta: quanto ti sei avvicinato?","Di solito ci serve almeno il doppio del tempo che pensiamo."],
 en:["1. Think of three things you need to do.\n2. Estimate how long each one will take.\n3. Do them and time them for real.\nCompare: how close were you?","It usually takes at least twice as long as we think."],
 es:["1. Piensa en tres cosas que tienes que hacer.\n2. Calcula cuánto tiempo te llevará cada una.\n3. Hazlas y mide el tiempo real.\nCompara: ¿cuánto te has acercado?","Normalmente necesitamos al menos el doble del tiempo que pensamos."]},
"solitario|IMMAGINAZIONE LIBERA":{
 it:["1. Chiudi gli occhi.\n2. Immagina un posto che ti piace davvero.\n3. Guarda ogni dettaglio: cosa vedi, cosa senti, che profumo c'è.\nRestaci 5 minuti, senza fretta.","È un modo semplice per staccare la testa."],
 en:["1. Close your eyes.\n2. Picture a place you really love.\n3. Notice every detail: what you see, what you hear, what it smells like.\nStay there for 5 minutes, no rush.","It's an easy way to switch off."],
 es:["1. Cierra los ojos.\n2. Imagina un lugar que te guste de verdad.\n3. Fíjate en cada detalle: qué ves, qué oyes, a qué huele.\nQuédate ahí 5 minutos, sin prisa.","Es una forma sencilla de desconectar."]},
"solitario|IL CONFRONTO CON IL PASSATO":{
 it:["Pensa a te di 5 anni fa:\n1. cosa lo stupirebbe di te oggi?\n2. cosa lo deluderebbe?\n3. cosa lo renderebbe orgoglioso?","Non è nostalgia: è capire quanta strada hai fatto."],
 en:["Think of yourself 5 years ago:\n1. what would surprise them about you today?\n2. what would disappoint them?\n3. what would make them proud?","It's not nostalgia: it's seeing how far you've come."],
 es:["Piensa en ti hace 5 años:\n1. ¿qué te sorprendería de ti hoy?\n2. ¿qué te decepcionaría?\n3. ¿qué te haría sentir orgulloso?","No es nostalgia: es ver cuánto camino has hecho."]},
"solitario|COSA VOGLIO DAVVERO?":{
 it:["1. Scrivi 10 cose che vuoi, senza filtri.\n2. Cancella quelle che vuoi solo perché gli altri se lo aspettano.\n3. Guarda cosa rimane.","Quello che resta è quello che conta davvero."],
 en:["1. Write down 10 things you want, no filter.\n2. Cross out the ones you only want because others expect it.\n3. Look at what's left.","What's left is what really matters."],
 es:["1. Escribe 10 cosas que quieres, sin filtro.\n2. Tacha las que quieres solo porque los demás lo esperan.\n3. Mira lo que queda.","Lo que queda es lo que de verdad importa."]},
// ───────────── INDOVINELLI ─────────────
"indovinelli|INDOVINELLI":{
 it:["1. Scegli un indovinello (puoi filtrarli per difficoltà).\n2. Leggilo ad alta voce al tavolo.\n3. Chi pensa di saperlo dice la risposta.\n4. Toccate «Scopri la risposta» per controllare.","Chi indovina sceglie l'indovinello dopo."],
 en:["1. Pick a riddle (you can filter by difficulty).\n2. Read it out loud to the table.\n3. Whoever thinks they know says the answer.\n4. Tap \"Reveal answer\" to check.","Whoever gets it right picks the next riddle."],
 es:["1. Elige un acertijo (puedes filtrarlos por dificultad).\n2. Léelo en voz alta a la mesa.\n3. Quien crea saberlo dice la respuesta.\n4. Tocad «Revelar respuesta» para comprobarlo.","Quien acierte elige el siguiente acertijo."]}
};
// Applica le regole a tutte le tabelle dei giochi (IT/EN/ES), dopo l'allineamento delle lingue
function applyRegole(){
 var tabs={it:(typeof GAMES!=="undefined"?GAMES:null),en:(typeof GAMES_EN!=="undefined"?GAMES_EN:null),es:(typeof GAMES_ES!=="undefined"?GAMES_ES:null)};
 Object.keys(tabs).forEach(function(L){
  var T2=tabs[L];if(!T2)return;
  Object.keys(T2).forEach(function(c){
   (T2[c]||[]).forEach(function(g){
    var r=REGOLE[c+"|"+(g._it||g.name)];if(!r)return;
    var v=r[L]||r.it;g.rules=v[0];g.tip=v[1]||"";if(r.p)g.players=r.p;
   });
  });
 });
}
// Regole per la schermata attuale (anche senza gioco scelto: giochi a distanza riaperti, indovinelli)
var REGOLE_SCREEN={cdr:"relax|INDOVINA IL CODICE",agr:"relax|ANNO GIUSTO",pdr:"relax|PRIMA O DOPO?",fgr:"relax|CHE BANDIERA È?",lgr:"relax|CHE LINGUA È?",qxr:"relax|QUANTO VALE?",ocr:"relax|L'OCCHIO DEI COLORI",tpr:"relax|IL TEMPO PERFETTO",riddle:"indovinelli|INDOVINELLI"};
function regoleNow(){
 try{
  var L=(typeof LANG!=="undefined"&&LANG)||"it";
  var k=REGOLE_SCREEN[S.screen];
  if(!k){var g=(typeof curGame==="function")?curGame():null;if(!g||!S.cat)return null;k=S.cat+"|"+(g._it||g.name);}
  var r=REGOLE[k];if(!r)return null;var v=r[L]||r.it;
  return {key:k,rules:v[0],tip:v[1]||""};
 }catch(e){return null;}
}
